-- =============================================================================
-- 453 — LE CAHIER D'EXERCICES DE TLE (partie 18)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 453 --niveau Tle --matieres si --suffixe 18 > supabase/contenu/453_exercices_tle_18.sql
--
-- 66 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   si.k194                 33 exercices · 11 chapitres
--   si.k195                 33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('b466f003-d477-534b-935a-293235541784'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La serre et son convertisseur","competence":"observer-schema","situation":"Une serre mesure sa température avec une thermistance. Le signal passe par un amplificateur, puis par un convertisseur analogique-numérique (CAN) de 12 bits alimenté sous 3,3 V, avant d’arriver au microcontrôleur.","documents":[{"id":"ch","type":"chaine","disposition":"ligne","titre":"Chaîne d’information de la serre","noeuds":[{"id":"z1","texte":"Thermistance"},{"id":"z2","texte":"Amplificateur"},{"id":"z3","texte":"CAN 12 bits"},{"id":"z4","texte":"Microcontrôleur"}],"liens":[{"de":"z1","a":"z2","texte":"tension faible"},{"de":"z2","a":"z3","texte":"tension adaptée"},{"de":"z3","a":"z4","texte":"nombre"}],"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche le bloc qui transforme la tension en nombre.","aide":"Le microcontrôleur ne comprend que des nombres, pas des tensions.","type":"zone","document":"ch","multiple":false},{"enonce":"Calcule le quantum du CAN, en mV, arrondi au centième.","aide":"q = U_ref / 2^n, avec 2^12 = 4 096 et U_ref = 3,3 V = 3 300 mV.","type":"nombre","unite":"mV"},{"enonce":"La thermistance et son amplificateur délivrent 1,65 V. Quel nombre le CAN renvoie-t-il ?","aide":"N = U / q : 1,65 V est exactement la moitié de la pleine échelle.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **CAN** (convertisseur analogique-numérique) transforme une tension en un nombre entier."},{"cle":{"type":"nombre","valeur":0.81,"tolerance":0.006},"affichage":"0,81 mV","explication":"q = 3 300 / 4 096 ≈ **0,81 mV** : c’est la plus petite variation que le CAN code."},{"cle":{"type":"nombre","valeur":2048,"tolerance":0},"affichage":"2048","explication":"N = 1,65 / (3,3 / 4 096) = **2 048**, soit la moitié des 4 096 niveaux."}]$ex$::jsonb),
  ('b466f003-d477-534b-935a-293235541784'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le capteur de pression du vérin","competence":"lire-graphique","situation":"Un capteur mesure la pression d’un vérin de 0 à 10 bar. Sa tension de sortie est reliée à un CAN de 10 bits et de pleine échelle 5 V. On cherche à tirer le meilleur de ce convertisseur.","documents":[{"id":"cap","type":"graphique","forme":"courbe","titre":"Tension de sortie du capteur","categories":["0","2","4","6","8","10"],"series":[{"nom":"Tension de sortie","valeurs":[0.5,0.9,1.3,1.7,2.1,2.5],"teinte":"violet"}],"axeY":{"titre":"Tension de sortie","unite":"V","min":0,"max":3,"pas":0.5},"axeX":{"titre":"Pression (bar)"},"valeurs":false,"source":"Situation imaginée pour l’exercice"},{"id":"can","type":"tableau","titre":"Le convertisseur","colonnes":["Caractéristique","Valeur"],"lignes":[["Nombre de bits",10],["Pleine échelle","5 V"]],"enteteLignes":true}],"questions":[{"enonce":"Lis sur la courbe la tension de sortie à 6 bar.","aide":"Repère 6 sur l’axe horizontal, puis monte jusqu’à la courbe.","type":"nombre","unite":"V"},{"enonce":"Calcule la sensibilité du capteur, en V par bar.","aide":"Divise la variation de tension (de 0 à 10 bar) par la variation de pression.","type":"nombre","unite":"V/bar"},{"enonce":"Un amplificateur multiplie la tension par un gain entier. Quel gain maximal évite de saturer le CAN sur toute la plage ?","aide":"La tension maximale du capteur est 2,5 V ; le CAN accepte au plus 5 V.","type":"nombre"},{"enonce":"Avec ce gain, la sensibilité devient 0,4 V/bar. Quelle pression minimale le CAN distingue-t-il ? Arrondis au millième de bar.","aide":"Calcule d’abord le quantum q = 5 / 1 024, en V, puis divise par 0,4 V/bar.","type":"nombre","unite":"bar"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":1.7,"tolerance":0.05},"affichage":"1,7 V","explication":"À 6 bar, la sortie vaut **1,7 V**."},{"cle":{"type":"nombre","valeur":0.2,"tolerance":0.005},"affichage":"0,2 V/bar","explication":"S = (2,5 − 0,5) / 10 = **0,2 V/bar**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Avec un gain de 2, la sortie maximale est **5 V**, pile la pleine échelle. Un gain de 3 donnerait 7,5 V : le CAN saturerait."},{"cle":{"type":"nombre","valeur":0.012,"tolerance":0.0006},"affichage":"0,012 bar","explication":"q = 5 / 1 024 ≈ 4,88 mV, donc la résolution vaut 4,88 / 400 ≈ **0,012 bar**, deux fois mieux que sans amplification."}]$ex$::jsonb),
  ('b466f003-d477-534b-935a-293235541784'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le codeur du tapis roulant","competence":"modeliser","situation":"Un codeur incrémental de 400 impulsions par tour est monté sur l’arbre d’un tapis. Un compteur relevé toutes les 50 ms donne le nombre d’impulsions reçues depuis le départ. Les deux voies du codeur sont notées A et B.","documents":[{"id":"rel","type":"tableau","titre":"Relevés du compteur","colonnes":["Instant (ms)","0","50","100","150"],"lignes":[["Compteur (impulsions)",0,100,200,300]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"},{"id":"voies","type":"tableau","titre":"Fronts montants des deux voies","colonnes":["Voie","Front montant à (ms)"],"lignes":[["A","2,0"],["B","2,5"]],"enteteLignes":true,"source":"Convention de l’atelier : l’arbre tourne dans le sens horaire quand la voie A monte avant la voie B."}],"questions":[{"enonce":"Quelle est la résolution angulaire du codeur, en degrés ?","aide":"Un tour fait 360° ; il donne 400 impulsions.","type":"nombre","unite":"°"},{"enonce":"Combien de tours l’arbre a-t-il faits en 150 ms ?","aide":"Lis le compteur à 150 ms, puis divise par le nombre d’impulsions d’un tour.","type":"nombre","unite":"tour"},{"enonce":"En déduis la vitesse de l’arbre, en tours par minute.","aide":"0,75 tour en 0,15 s : combien de tours en 1 s, puis en 60 s ?","type":"nombre","unite":"tr/min"},{"enonce":"Dans quel sens tourne l’arbre ?","aide":"Compare les deux instants du tableau avec la convention donnée sous le tableau.","type":"choix","options":[{"id":"a","texte":"Sens horaire, car la voie A monte avant la voie B"},{"id":"b","texte":"Sens anti-horaire, car la voie A monte avant la voie B"},{"id":"c","texte":"On ne peut pas le savoir : il faudrait une troisième voie"},{"id":"d","texte":"Sens anti-horaire, car la voie B monte après la voie A"}],"multiple":false},{"enonce":"Quelle est la fréquence des impulsions d’une voie, en Hz ?","aide":"Entre deux relevés, 100 impulsions arrivent en 50 ms.","type":"nombre","unite":"Hz"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.9,"tolerance":0},"affichage":"0,9 °","explication":"r = 360 / 400 = **0,9°** par impulsion."},{"cle":{"type":"nombre","valeur":0.75,"tolerance":0},"affichage":"0,75 tour","explication":"300 / 400 = **0,75 tour**."},{"cle":{"type":"nombre","valeur":300,"tolerance":0},"affichage":"300 tr/min","explication":"0,75 / 0,15 = 5 tours par seconde, soit **300 tr/min**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La voie A monte à 2,0 ms, avant la voie B (2,5 ms) : c’est la convention du **sens horaire**. Le décalage des deux voies sert exactement à cela."},{"cle":{"type":"nombre","valeur":2000,"tolerance":0},"affichage":"2000 Hz","explication":"100 impulsions en 0,05 s : 100 / 0,05 = **2 000 Hz**."}]$ex$::jsonb),
  ('b71fc46a-e108-52ce-a4a8-96157419e849'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le message du robot","competence":"lire-tableau","situation":"Un robot envoie les deux caractères « GO » à sa carte de commande par une liaison UART à 9 600 bauds. Chaque caractère est un octet encadré comme le montre la trame.","documents":[{"id":"trame","type":"tableau","titre":"La trame d’un octet","colonnes":["Élément de la trame","Nombre de bits"],"lignes":[["Bit de départ",1],["Données",8],["Parité",0],["Bit d’arrêt",1]],"enteteLignes":true,"source":"Format 8N1 : 8 bits de données, pas de parité, 1 bit d’arrêt."}],"questions":[{"enonce":"Touche l’élément de la trame qui réveille le récepteur.","aide":"C’est lui qui ouvre la trame.","type":"zone","document":"trame","multiple":false},{"enonce":"Combien de bits sont transmis pour envoyer « GO » (2 octets) ?","aide":"Additionne les bits d’une trame, puis double.","type":"nombre","unite":"bits"},{"enonce":"Combien de temps dure l’envoi du message à 9 600 bauds ? Arrondis au centième de milliseconde.","aide":"Durée = nombre de bits / débit, avec 9 600 bits par seconde.","type":"nombre","unite":"ms"},{"enonce":"Quel est le débit utile, c’est-à-dire le nombre de bits de données par seconde ?","aide":"Sur 10 bits transmis, seuls 8 sont des données.","type":"nombre","unite":"bit/s"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"Le **bit de départ** réveille le récepteur et lui signale qu’un octet arrive."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 bits","explication":"1 + 8 + 0 + 1 = 10 bits par octet, donc 2 × 10 = **20 bits**."},{"cle":{"type":"nombre","valeur":2.08,"tolerance":0.01},"affichage":"2,08 ms","explication":"20 / 9 600 ≈ 0,00208 s, soit **2,08 ms**."},{"cle":{"type":"nombre","valeur":7680,"tolerance":0},"affichage":"7680 bit/s","explication":"9 600 × 8 / 10 = **7 680 bit/s** : l’encadrement de la trame coûte 20 % du débit."}]$ex$::jsonb),
  ('b71fc46a-e108-52ce-a4a8-96157419e849'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un écran, une carte SD, un GPS","competence":"analyser-document","situation":"Un robot doit dialoguer avec trois modules. Le microcontrôleur n’a plus que quelques broches libres : il faut bien choisir le bus de chaque module.","documents":[{"id":"mod","type":"tableau","titre":"Les trois modules","colonnes":["Module","Broches utilisées","Particularité"],"lignes":[["A (écran)","SDA, SCL","Adresse sur 7 bits"],["B (carte SD)","MOSI, MISO, SCK, CS","Fil CS propre au module"],["C (GPS)","TX, RX","Pas d’horloge, débit convenu"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Associe chaque module au bus qu’il utilise.","aide":"Regarde le nom des broches utilisées.","type":"association","gauche":[{"id":"g0","texte":"Module A"},{"id":"g1","texte":"Module B"},{"id":"g2","texte":"Module C"}],"droite":[{"id":"d0","texte":"I2C"},{"id":"d1","texte":"UART"},{"id":"d2","texte":"SPI"}]},{"enonce":"Combien de fils (hors alimentation et masse) faut-il pour relier TROIS modules I2C au microcontrôleur ?","aide":"Sur un bus I2C, tous les modules partagent les mêmes fils.","type":"nombre","unite":"fils"},{"enonce":"Et pour relier trois modules SPI comme le module B ? SCK, MOSI et MISO sont partagés ; chaque module a son propre fil CS.","aide":"Trois fils partagés, plus un fil de sélection par module.","type":"nombre","unite":"fils"},{"enonce":"Combien d’adresses différentes permet d’obtenir une adresse I2C sur 7 bits ?","aide":"Avec n bits, on code 2^n valeurs.","type":"nombre","unite":"adresses"},{"enonce":"Il ne reste que 3 broches libres pour relier trois modules identiques. Quel bus choisir ?","aide":"Compte les fils dont chaque bus a besoin pour trois modules.","type":"choix","options":[{"id":"a","texte":"Bus parallèle : huit fils de données seulement, en plus de l’horloge"},{"id":"b","texte":"UART : un couple TX et RX serait partagé entre les trois modules"},{"id":"c","texte":"SPI : il faudrait un fil de sélection par module, donc six fils au total"},{"id":"d","texte":"I2C : deux fils suffisent pour tout le bus, chaque module a son adresse"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"SDA et SCL : **I2C**. MOSI, MISO, SCK et CS : **SPI**. TX et RX sans horloge : **UART**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 fils","explication":"Les trois modules se branchent sur les mêmes fils **SDA et SCL** : 2 fils suffisent."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 fils","explication":"3 fils partagés + 3 fils CS = **6 fils**."},{"cle":{"type":"nombre","valeur":128,"tolerance":0},"affichage":"128 adresses","explication":"2^7 = **128 adresses**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Seul l’**I2C** tient dans 3 broches : 2 fils pour tout le bus. Le SPI en demande 6, l’UART est point à point et un bus parallèle exigerait encore plus de fils."}]$ex$::jsonb),
  ('b71fc46a-e108-52ce-a4a8-96157419e849'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quelle liaison tient en 20 ms ?","competence":"modeliser","situation":"Une centrale inertielle doit renvoyer une trame de 250 octets de données toutes les 20 ms. Quatre liaisons sont envisagées ; il faut choisir celles dont la durée d’envoi reste inférieure à la période.","documents":[{"id":"lia","type":"tableau","titre":"Les liaisons envisagées","colonnes":["Liaison","Débit brut","Bits par octet"],"lignes":[["UART 115 200 bauds","115 200 bit/s",10],["I2C standard","100 kbit/s",9],["I2C rapide","400 kbit/s",9],["SPI","1 Mbit/s",8]],"enteteLignes":true,"source":"I2C : un bit d’acquittement par octet, plus un octet d’adresse en début de message ; on néglige départ et arrêt."},{"id":"cdc","type":"texte","genre":"consigne","titre":"Cahier des charges","auteur":"Situation imaginée pour l’exercice","blocs":["Trame : 250 octets de données","Période d’envoi : 20 ms","Durée d’envoi : strictement inférieure à la période"]}],"questions":[{"enonce":"Quelle est la durée d’envoi de la trame en UART à 115 200 bauds ? Arrondis au centième de milliseconde.","aide":"Nombre de bits = 250 × 10 ; durée = bits / débit.","type":"nombre","unite":"ms"},{"enonce":"Et en I2C standard (100 kbit/s) ? N’oublie pas l’octet d’adresse. Arrondis au centième de milliseconde.","aide":"Il y a 250 + 1 octets, de 9 bits chacun.","type":"nombre","unite":"ms"},{"enonce":"Et en SPI à 1 Mbit/s ? Donne la durée en ms.","aide":"250 octets de 8 bits, à 1 000 000 bits par seconde.","type":"nombre","unite":"ms"},{"enonce":"Touche les deux liaisons qui respectent le cahier des charges.","aide":"Compare chaque durée à 20 ms. L’I2C rapide va 4 fois plus vite que l’I2C standard.","type":"zone","document":"lia","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":21.7,"tolerance":0.05},"affichage":"21,7 ms","explication":"2 500 bits / 115 200 ≈ **21,70 ms** : c’est plus que 20 ms."},{"cle":{"type":"nombre","valeur":22.59,"tolerance":0.05},"affichage":"22,59 ms","explication":"251 × 9 = 2 259 bits, soit 2 259 / 100 000 ≈ **22,59 ms**, encore trop long."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 ms","explication":"2 000 bits / 1 000 000 = 0,002 s, soit **2 ms**."},{"cle":{"type":"zone","ids":["r2c0","r3c0"]},"explication":"L’**I2C rapide** (2 259 / 400 000 ≈ 5,6 ms) et le **SPI** (2 ms) tiennent dans 20 ms ; l’UART et l’I2C standard dépassent la période."}]$ex$::jsonb),
  ('28322603-40df-540b-a330-633aec5834de'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La barrière du parking","competence":"observer-schema","situation":"La barrière d’un parking d’entreprise est décrite par son diagramme d’états : chaque flèche porte l’événement qui déclenche le changement d’état.","documents":[{"id":"diag","type":"chaine","disposition":"cycle","titre":"Diagramme d’états de la barrière","noeuds":[{"id":"z1","texte":"Fermée"},{"id":"z2","texte":"Ouverture"},{"id":"z3","texte":"Ouverte"},{"id":"z4","texte":"Fermeture"}],"liens":[{"de":"z1","a":"z2","texte":"ticket inséré"},{"de":"z2","a":"z3","texte":"fin de course haut"},{"de":"z3","a":"z4","texte":"véhicule passé"},{"de":"z4","a":"z1","texte":"fin de course bas"}],"source":"Diagramme imaginé pour l’exercice"}],"questions":[{"enonce":"Touche l’état dans lequel se trouve la barrière pendant qu’un véhicule passe.","aide":"La barrière doit être complètement levée.","type":"zone","document":"diag","multiple":false},{"enonce":"Un second conducteur insère un ticket alors que la barrière est Ouverte. D’après le diagramme, que se passe-t-il ?","aide":"Cherche les flèches qui partent de l’état Ouverte.","type":"choix","options":[{"id":"a","texte":"La barrière passe aussitôt à l’état Fermeture, par sécurité"},{"id":"b","texte":"La barrière repasse à l’état Ouverture pour accueillir le ticket"},{"id":"c","texte":"La barrière revient à l’état Fermée en sautant l’état Fermeture"},{"id":"d","texte":"Rien : aucune flèche ne part de Ouverte sur cet événement"}],"multiple":false},{"enonce":"Combien d’événements différents faut-il pour faire un tour complet du diagramme, de Fermée jusqu’au retour à Fermée ?","aide":"Compte les flèches du cycle.","type":"nombre","unite":"événements"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Le véhicule passe quand la barrière est **Ouverte** : elle a atteint la fin de course haut."},{"cle":{"type":"choix","ids":["d"]},"explication":"Depuis **Ouverte**, la seule flèche attend « véhicule passé ». Le ticket est ignoré : un événement sans transition ne change rien."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 événements","explication":"Il y a une flèche par changement d’état : ticket, fin de course haut, véhicule passé, fin de course bas, soit **4 événements**."}]$ex$::jsonb),
  ('28322603-40df-540b-a330-633aec5834de'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le portail qui n’écoute pas","competence":"programmer","situation":"Un élève a traduit en programme le diagramme d’états d’un portail. Il le compare au tableau des transitions du cahier des charges et trouve que le portail ne réagit pas toujours comme prévu.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"Programme du portail","auteur":"Programme écrit pour l’exercice","blocs":["état ← Fermé","répéter indéfiniment","    lire appui, fin_haut, fin_bas","    si état = Fermé et appui alors état ← Ouverture","    si état = Ouverture et fin_haut alors état ← Ouvert","    si état = Ouvert et temporisation écoulée alors état ← Fermeture","    si état = Fermeture et fin_bas alors état ← Fermé"]},{"id":"cdc","type":"tableau","titre":"Transitions attendues","colonnes":["État de départ","Événement","État d’arrivée"],"lignes":[["Fermé","appui","Ouverture"],["Ouverture","fin_haut","Ouvert"],["Ouvert","temporisation écoulée","Fermeture"],["Fermeture","obstacle","Ouverture"],["Fermeture","fin_bas","Fermé"]],"enteteLignes":true,"source":"Cahier des charges imaginé pour l’exercice"}],"questions":[{"enonce":"Que fait ce programme si un obstacle est détecté pendant la fermeture ?","aide":"Cherche dans le programme une ligne qui parle d’obstacle.","type":"choix","options":[{"id":"a","texte":"Il passe à l’état Fermé sans attendre la fin de course"},{"id":"b","texte":"Il rouvre aussitôt le portail, comme le demande le cahier"},{"id":"c","texte":"Il s’arrête dans l’état Fermeture jusqu’à une action"},{"id":"d","texte":"Il continue de fermer : aucun test ne réagit à l’obstacle"}],"multiple":false},{"enonce":"Complète la ligne à ajouter pour corriger le programme.","aide":"Relis la ligne « Fermeture / obstacle » du tableau.","type":"trous","segments":["si état = ",0," et ",1," alors état ← ",2],"banque":["Ouverture","obstacle","fin_bas","appui","Fermeture","Ouvert"]},{"enonce":"Le portail est dans l’état Ouverture et fin_haut vient d’être détecté. Quel est l’état après ce tour de boucle ? (un mot)","aide":"Cherche la ligne du programme qui teste fin_haut.","type":"texte"},{"enonce":"L’appui sur la télécommande dure 80 ms et un tour de boucle dure 10 ms. Combien de tours de boucle lisent « appui » ?","aide":"Divise la durée de l’appui par la durée d’un tour.","type":"nombre","unite":"tours"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Le programme ne contient **aucun test sur l’obstacle** : la transition « Fermeture → Ouverture » du cahier des charges a été oubliée, et c’est la plus importante pour la sécurité."},{"cle":{"type":"trous","trous":[["fermeture"],["obstacle"],["ouverture"]]},"affichage":"Fermeture · obstacle · Ouverture","explication":"La ligne manquante est : **si état = Fermeture et obstacle alors état ← Ouverture**."},{"cle":{"type":"texte","acceptes":["ouvert"]},"affichage":"Ouvert","explication":"Le test « si état = Ouverture et fin_haut » passe l’état à **Ouvert**."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 tours","explication":"80 / 10 = **8 tours**. Seul le premier change l’état : les suivants ne passent plus le test « état = Fermé »."}]$ex$::jsonb),
  ('28322603-40df-540b-a330-633aec5834de'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les impulsions qu’on ne voit pas passer","competence":"programmer","situation":"Un microcontrôleur compte les impulsions d’un codeur monté sur un moteur rapide. Un premier programme relevait l’entrée une fois par tour de boucle et perdait des impulsions. On le remplace par une routine déclenchée par le matériel.","documents":[{"id":"don","type":"tableau","titre":"Données du système","colonnes":["Donnée","Valeur"],"lignes":[["Vitesse du moteur","3 000 tr/min"],["Impulsions par tour",500],["Durée d’un tour de boucle","1 ms"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"},{"id":"isr","type":"texte","genre":"consigne","titre":"Routine d’interruption","auteur":"Programme écrit pour l’exercice","blocs":["à chaque front montant de la voie A :","    si la voie B = 0","        compteur ← compteur + 1","    sinon","        compteur ← compteur − 1"]}],"questions":[{"enonce":"Quelle est la fréquence des impulsions d’une voie, en Hz ?","aide":"Tours par seconde × impulsions par tour.","type":"nombre","unite":"Hz"},{"enonce":"Quelle durée sépare deux impulsions successives, en µs ?","aide":"La période est l’inverse de la fréquence.","type":"nombre","unite":"µs"},{"enonce":"Combien d’impulsions arrivent pendant un seul tour de boucle de 1 ms ?","aide":"Divise 1 000 µs par la durée entre deux impulsions.","type":"nombre","unite":"impulsions"},{"enonce":"Quelle méthode permet de ne manquer aucune impulsion ?","aide":"Il faut que le matériel prévienne le programme à chaque impulsion.","type":"choix","options":[{"id":"a","texte":"Aucune : un microcontrôleur ne sait pas compter aussi vite"},{"id":"b","texte":"L’interruption : chaque impulsion suspend le programme le temps de la compter"},{"id":"c","texte":"La scrutation, en ajoutant un anti-rebond logiciel plus long"},{"id":"d","texte":"La scrutation, en lisant l’entrée une seule fois par tour de boucle"}],"multiple":false},{"enonce":"À quoi sert le test « si la voie B = 0 » dans la routine ?","aide":"Rappelle-toi le rôle des deux voies décalées.","type":"choix","options":[{"id":"a","texte":"À compter deux fois plus d’impulsions à chaque tour"},{"id":"b","texte":"À vérifier que le codeur est bien alimenté en continu"},{"id":"c","texte":"À éliminer les rebonds de la voie A avant de compter"},{"id":"d","texte":"À connaître le sens de rotation, pour compter ou décompter"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":25000,"tolerance":0},"affichage":"25 000 Hz","explication":"3 000 / 60 = 50 tours par seconde, donc 50 × 500 = **25 000 Hz**."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 µs","explication":"1 / 25 000 = 0,000 04 s, soit **40 µs**."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 impulsions","explication":"1 000 / 40 = **25 impulsions** : relire l’entrée une fois par tour en manquerait presque toutes."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec une **interruption**, le matériel suspend le programme dès qu’un front arrive. La scrutation, même améliorée, reste limitée par la durée du tour de boucle."},{"cle":{"type":"choix","ids":["d"]},"explication":"Selon l’état de la voie B au moment du front de A, l’arbre tourne dans un sens ou dans l’autre : le **sens de rotation** décide d’ajouter ou de retirer 1."}]$ex$::jsonb),
  ('f357b47e-2a08-5d33-bda5-3f7851e9d901'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La station météo du champ","competence":"observer-schema","situation":"Une station météo posée à 3 km de la ferme mesure la température et l’humidité. Alimentée par une pile, elle envoie quelques octets par heure vers une application sur le téléphone de l’agriculteur.","documents":[{"id":"arch","type":"chaine","disposition":"ligne","titre":"Architecture de la solution","noeuds":[{"id":"z1","texte":"Station météo"},{"id":"z2","texte":"Passerelle"},{"id":"z3","texte":"Serveur"},{"id":"z4","texte":"Application"}],"liens":[{"de":"z1","a":"z2","texte":"radio"},{"de":"z2","a":"z3","texte":"Internet"},{"de":"z3","a":"z4","texte":"données"}],"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche le maillon qui reçoit la radio et la relaie vers Internet.","aide":"Il fait le lien entre l’objet et Internet.","type":"zone","document":"arch","multiple":false},{"enonce":"Alimentée par une pile, la station est à 3 km et n’envoie que quelques octets par heure. Quelle technologie radio convient le mieux ?","aide":"Regarde ce qui compte ici : la portée, et la pile.","type":"choix","options":[{"id":"a","texte":"Bluetooth basse consommation : sobre, mais portée de quelques dizaines de mètres"},{"id":"b","texte":"Réseau cellulaire : large couverture, mais consommation élevée et abonnement"},{"id":"c","texte":"Wi-Fi : fort débit, mais une portée de quelques dizaines de mètres"},{"id":"d","texte":"LoRa : grande portée et très faible consommation, le faible débit suffit"}],"multiple":false},{"enonce":"La station consomme 24 mA pendant 1 s toutes les 300 s ; on néglige sa consommation en veille. Quelle est sa consommation moyenne, en mA ?","aide":"I_moy = I_actif × (t_actif / T).","type":"nombre","unite":"mA"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La **passerelle** reçoit les messages radio de l’objet et les relaie vers le serveur par Internet."},{"cle":{"type":"choix","ids":["d"]},"explication":"**LoRa** couvre plusieurs kilomètres pour très peu d’énergie. Son débit est faible, mais quelques octets par heure n’en demandent pas plus."},{"cle":{"type":"nombre","valeur":0.08,"tolerance":0.005},"affichage":"0,08 mA","explication":"24 × 1 / 300 = **0,08 mA** : l’objet dort presque tout le temps."}]$ex$::jsonb),
  ('f357b47e-2a08-5d33-bda5-3f7851e9d901'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"L’autonomie du capteur de parking","competence":"calculer","situation":"Un capteur de place de parking mesure et émet une fois par minute, puis se rendort. Il est alimenté par une pile de 2 400 mAh. Le tableau donne son cycle de 60 s.","documents":[{"id":"cyc","type":"tableau","titre":"Cycle de 60 secondes","colonnes":["Mode","Courant","Durée par cycle"],"lignes":[["Émission radio","40 mA","0,5 s"],["Mesure","5 mA","1 s"],["Veille","8 µA","58,5 s"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche le mode dans lequel le capteur passe le plus de temps.","aide":"Compare la dernière colonne.","type":"zone","document":"cyc","multiple":false},{"enonce":"Quelle charge l’émission radio consomme-t-elle par cycle, en mA·s ?","aide":"Charge = courant × durée.","type":"nombre","unite":"mA·s"},{"enonce":"Calcule la consommation moyenne sur un cycle, en mA, arrondie au centième.","aide":"Additionne les charges des trois modes (la veille : 0,008 mA × 58,5 s), puis divise par 60 s.","type":"nombre","unite":"mA"},{"enonce":"En déduis l’autonomie de la pile, en jours, arrondie à l’unité.","aide":"Autonomie en heures = 2 400 mAh / I_moy ; divise ensuite par 24.","type":"nombre","unite":"jours"},{"enonce":"Comment presque doubler l’autonomie ?","aide":"La consommation moyenne dépend surtout du nombre d’émissions par heure.","type":"choix","options":[{"id":"a","texte":"Mesurer deux fois plus longtemps à chaque cycle de 60 s"},{"id":"b","texte":"Doubler la durée de chaque émission radio pour la fiabiliser"},{"id":"c","texte":"Remplacer l’antenne par une antenne plus longue et plus fine"},{"id":"d","texte":"Envoyer une mesure toutes les 2 minutes au lieu d’une par minute"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Le capteur est en **veille** 58,5 s sur 60 : il dort presque tout le temps."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 mA·s","explication":"40 × 0,5 = **20 mA·s**."},{"cle":{"type":"nombre","valeur":0.42,"tolerance":0.005},"affichage":"0,42 mA","explication":"(20 + 5 + 0,468) / 60 ≈ **0,42 mA**."},{"cle":{"type":"nombre","valeur":237,"tolerance":3},"affichage":"237 jours","explication":"2 400 / 0,42 ≈ 5 650 à 5 700 h, soit environ **236 jours** : à peine plus de sept mois."},{"cle":{"type":"choix","ids":["d"]},"explication":"Avec un cycle de 120 s, la charge d’un cycle reste voisine de 26 mA·s mais elle est divisée par 120 : la consommation moyenne passe à 0,22 mA, soit une autonomie **presque doublée**."}]$ex$::jsonb),
  ('f357b47e-2a08-5d33-bda5-3f7851e9d901'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un objet, une technologie","competence":"analyser-document","situation":"Trois objets connectés doivent être livrés cette semaine. Il faut choisir pour chacun la technologie radio adaptée, estimer un temps d’envoi, puis penser à la sécurité.","documents":[{"id":"tec","type":"tableau","titre":"Les technologies","colonnes":["Technologie","Portée","Débit","Consommation"],"lignes":[["Bluetooth basse consommation","≈ 30 m","≈ 1 Mbit/s","Très faible"],["Wi-Fi","≈ 50 m","≈ 50 Mbit/s","Élevée"],["LoRa","≈ 5 km","≈ 300 bit/s","Très faible"]],"enteteLignes":true,"source":"Valeurs typiques arrondies"},{"id":"bes","type":"tableau","titre":"Les besoins","colonnes":["Objet","Distance","Données à envoyer","Alimentation"],"lignes":[["Capteur de benne","4 km","10 octets par heure","Pile"],["Bracelet de sport","2 m (téléphone)","Quelques ko par minute","Petite batterie"],["Caméra de bureau","20 m (box)","2 Mbit/s en continu","Secteur"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Associe chaque objet à la technologie la plus adaptée.","aide":"Croise la distance, le débit et l’alimentation.","type":"association","gauche":[{"id":"g0","texte":"Capteur de benne"},{"id":"g1","texte":"Bracelet de sport"},{"id":"g2","texte":"Caméra de bureau"}],"droite":[{"id":"d0","texte":"Bluetooth basse consommation"},{"id":"d1","texte":"Wi-Fi"},{"id":"d2","texte":"LoRa"}]},{"enonce":"Combien de temps faut-il à LoRa pour envoyer les 10 octets du capteur de benne, au débit de 300 bit/s ? Arrondis au centième de seconde.","aide":"Convertis d’abord 10 octets en bits.","type":"nombre","unite":"s"},{"enonce":"Complète la phrase qui décrit la publication des mesures.","aide":"L’objet ne connaît pas ses destinataires : un intermédiaire redistribue.","type":"trous","segments":["Le capteur ",0," sa mesure sur un sujet auprès du ",1," ; l’application s’",2," à ce sujet pour la recevoir."],"banque":["publie","serveur","courtier","passerelle","abonne"]},{"enonce":"Tous les capteurs sortent d’usine avec le même mot de passe « 1234 ». Quelle parade règle ce risque ?","aide":"Le danger vient d’un secret connu de tout le monde.","type":"choix","options":[{"id":"a","texte":"Installer une antenne plus longue pour mieux capter le signal"},{"id":"b","texte":"Utiliser une pile plus grosse pour que le capteur dure plus longtemps"},{"id":"c","texte":"Faire émettre le capteur plus souvent pour détecter les intrusions"},{"id":"d","texte":"Donner à chaque capteur un identifiant et un mot de passe uniques"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"La benne est à 4 km, avec presque rien à envoyer : **LoRa**. Le bracelet est à 2 m de son téléphone, sur batterie : **Bluetooth basse consommation**. La caméra demande 2 Mbit/s sur le secteur : **Wi-Fi**."},{"cle":{"type":"nombre","valeur":0.27,"tolerance":0.005},"affichage":"0,27 s","explication":"10 octets = 80 bits, donc 80 / 300 ≈ **0,27 s**. Le faible débit n’est pas gênant pour un message aussi court."},{"cle":{"type":"trous","trous":[["publie"],["courtier"],["abonne"]]},"affichage":"publie · courtier · abonne","explication":"Le capteur **publie** sur un sujet auprès du **courtier** (broker) ; l’application **s’abonne** et reçoit les messages sans que l’objet la connaisse."},{"cle":{"type":"choix","ids":["d"]},"explication":"Un **identifiant unique par objet** empêche qu’un mot de passe connu ouvre tous les capteurs. La pile et l’antenne n’ont aucun rapport avec la sécurité."}]$ex$::jsonb),
  ('388ca274-5b45-5bf2-be52-eae4d56f6ff6'::uuid, 1, 1, 5, 20, 3,
