  ('388ca274-5b45-5bf2-be52-eae4d56f6ff6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les plus proches voisins","competence":"raisonner","situation":"Un modèle des k plus proches voisins doit classer une nouvelle pièce N, de 18 mm de long et 8 g. La distance entre deux pièces vaut √((écart de longueur)² + (écart de masse)²).","documents":[{"id":"ex","type":"tableau","titre":"Exemples étiquetés","colonnes":["Pièce","Longueur (mm)","Masse (g)","Classe"],"lignes":[["P1",10,5,"Conforme"],["P2",12,6,"Conforme"],["P3",20,9,"Défectueuse"],["P4",22,8,"Défectueuse"],["P5",14,7,"Conforme"]],"enteteLignes":true,"source":"Données imaginées pour l’exercice"}],"questions":[{"enonce":"Touche la pièce la plus proche de N.","aide":"Calcule les cinq distances, ou cherche les pièces dont longueur et masse sont les plus voisines de 18 et 8.","type":"zone","document":"ex","multiple":false},{"enonce":"Calcule la distance entre N et P5, arrondie au centième.","aide":"Écarts : 18 − 14 en longueur, 8 − 7 en masse.","type":"nombre"},{"enonce":"Avec k = 3, quelle classe le modèle donne-t-il à N ?","aide":"Les trois plus proches sont P3, P4 et P5 : regarde leur classe.","type":"choix","options":[{"id":"a","texte":"Conforme : P1 est la plus proche et elle est conforme"},{"id":"b","texte":"Défectueuse : les trois voisins les plus proches le sont"},{"id":"c","texte":"Défectueuse : deux des trois voisins les plus proches le sont"},{"id":"d","texte":"Conforme : deux des trois voisins les plus proches le sont"}],"multiple":false},{"enonce":"Avec k = 5, tous les exemples votent. Que devient la classe de N ?","aide":"Compte les classes des cinq pièces du tableau.","type":"choix","options":[{"id":"a","texte":"Défectueuse : les deux plus proches sont défectueuses"},{"id":"b","texte":"Conforme : trois des cinq exemples sont conformes"},{"id":"c","texte":"Égalité : le modèle ne peut pas choisir"},{"id":"d","texte":"Conforme : les trois plus proches sont conformes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"La pièce **P3** est la plus proche : √(2² + 1²) ≈ 2,24, contre 4,0 pour P4, 4,12 pour P5, 6,32 pour P2 et 8,54 pour P1."},{"cle":{"type":"nombre","valeur":4.12,"tolerance":0.005},"affichage":"4,12","explication":"√(4² + 1²) = √17 ≈ **4,12**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les 3 plus proches sont P3 (défectueuse), P4 (défectueuse) et P5 (conforme) : la classe majoritaire est **défectueuse**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec k = 5, on compte **3 conformes** (P1, P2, P5) contre 2 défectueuses : la classe de N change. Le choix de k compte."}]$ex$::jsonb),
  ('388ca274-5b45-5bf2-be52-eae4d56f6ff6'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quand le modèle apprend par cœur","competence":"lire-graphique","situation":"Une équipe fait varier la complexité d’un modèle de tri de pièces, de 1 à 6, et mesure son erreur sur le jeu d’entraînement et sur un jeu de test de 200 pièces jamais vues.","documents":[{"id":"err","type":"graphique","forme":"courbe","titre":"Erreur selon la complexité du modèle","categories":["1","2","3","4","5","6"],"series":[{"nom":"Entraînement","valeurs":[30,20,12,6,2,0],"teinte":"bleu"},{"nom":"Test","valeurs":[32,23,16,14,19,27],"teinte":"corail"}],"axeY":{"titre":"Erreur","unite":"%","min":0,"max":40,"pas":10},"axeX":{"titre":"Complexité du modèle"},"valeurs":false,"source":"Mesures imaginées pour l’exercice"},{"id":"jeu","type":"tableau","titre":"Jeu de test","colonnes":["Donnée","Valeur"],"lignes":[["Pièces du jeu de test",200]],"enteteLignes":true}],"questions":[{"enonce":"Touche la complexité pour laquelle l’erreur sur le jeu de test est la plus basse.","aide":"Suis la courbe du jeu de test, pas celle de l’entraînement.","type":"zone","document":"err","multiple":false},{"enonce":"Pour la complexité 6, de combien de points l’erreur de test dépasse-t-elle l’erreur d’entraînement ?","aide":"Lis les deux courbes en 6 et soustrais.","type":"nombre","unite":"points"},{"enonce":"Comment s’appelle le défaut du modèle de complexité 6 ?","aide":"Compare l’erreur à l’entraînement et l’erreur au test.","type":"choix","options":[{"id":"a","texte":"Saturation : le modèle dépasse la pleine échelle du CAN"},{"id":"b","texte":"Sous-apprentissage : le modèle est trop simple pour le problème"},{"id":"c","texte":"Surapprentissage : erreur nulle à l’entraînement mais forte au test"},{"id":"d","texte":"Biais des données : l’erreur est élevée sur les deux jeux"}],"multiple":false},{"enonce":"On retient la complexité 4. Combien de pièces du jeu de test sont mal classées ?","aide":"Applique 14 % à 200 pièces.","type":"nombre","unite":"pièces"},{"enonce":"Pourquoi ne choisit-on pas le modèle d’après son erreur d’entraînement ?","aide":"Regarde ce que fait la courbe d’entraînement quand la complexité augmente.","type":"choix","options":[{"id":"a","texte":"Elle dépend uniquement du nombre de pièces du jeu de test"},{"id":"b","texte":"Elle continue de baisser même quand le modèle apprend le bruit par cœur"},{"id":"c","texte":"Elle est toujours plus grande que l’erreur mesurée sur le jeu de test"},{"id":"d","texte":"Elle ne peut pas être calculée puisque les données sont étiquetées"}],"multiple":false}]}$ex$::jsonb,
