   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La **roue de 60 dents** est entraînée par le pignon : c’est la pièce menée."},{"cle":{"type":"nombre","valeur":0.25,"tolerance":0},"affichage":"0,25","explication":"15 / 60 = **0,25** : la roue tourne quatre fois moins vite."},{"cle":{"type":"nombre","valeur":375,"tolerance":0},"affichage":"375 tr/min","explication":"1 500 × 0,25 = **375 tr/min**."},{"cle":{"type":"nombre","valeur":1.44,"tolerance":0.01},"affichage":"1,44 N·m","explication":"0,9 × 0,4 / 0,25 = **1,44 N·m** : on a perdu en vitesse, on a gagné en couple."}]$ex$::jsonb),
  ('6495cb80-3de3-5d76-b8b5-7844be6c7094'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La porte coulissante","competence":"calculer","situation":"La porte coulissante d’un magasin est tirée par une crémaillère. Le moteur tourne à 4 500 tr/min ; un réducteur divise sa vitesse par 30 ; le pignon de sortie a un rayon primitif de 16 mm. La porte s’ouvre sur 1,2 m.","documents":[{"id":"ch","type":"chaine","disposition":"ligne","titre":"Chaîne de transmission de la porte","noeuds":[{"id":"z1","texte":"Moteur 4 500 tr/min"},{"id":"z2","texte":"Réducteur 1/30"},{"id":"z3","texte":"Pignon-crémaillère R = 16 mm"},{"id":"z4","texte":"Porte"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}],"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche l’élément qui transforme la rotation en translation.","aide":"Un engrenage ordinaire reste une rotation ; cherche le dispositif qui fait avancer une pièce en ligne droite.","type":"zone","document":"ch","multiple":false},{"enonce":"Quelle est la vitesse angulaire du pignon, en rad/s ? Arrondis au dixième.","aide":"Le réducteur donne 4 500 / 30 tours par minute ; puis ω = 2π × N / 60.","type":"nombre","unite":"rad/s"},{"enonce":"Quelle est la vitesse de la porte, en m/s ? Arrondis au centième.","aide":"v = ω × R, avec R en mètres (16 mm = 0,016 m).","type":"nombre","unite":"m/s"},{"enonce":"Combien de temps met la porte pour s’ouvrir sur 1,2 m ? Arrondis au dixième de seconde.","aide":"Durée = distance / vitesse.","type":"nombre","unite":"s"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **pignon-crémaillère** transforme la rotation du pignon en translation de la crémaillère."},{"cle":{"type":"nombre","valeur":15.7,"tolerance":0.05},"affichage":"15,7 rad/s","explication":"4 500 / 30 = 150 tr/min, soit ω = 2π × 150 / 60 ≈ **15,7 rad/s**."},{"cle":{"type":"nombre","valeur":0.25,"tolerance":0.005},"affichage":"0,25 m/s","explication":"v = 15,7 × 0,016 ≈ **0,25 m/s**."},{"cle":{"type":"nombre","valeur":4.8,"tolerance":0.1},"affichage":"4,8 s","explication":"1,2 / 0,25 ≈ **4,8 s**."}]$ex$::jsonb),
  ('6495cb80-3de3-5d76-b8b5-7844be6c7094'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le lit médical qui ne redescend pas","competence":"modeliser","situation":"Un lit médical se lève par une vis-écrou entraînée par un moteur et un engrenage. Quand le moteur s’arrête, le plateau reste en place. On veut connaître la vitesse de levée, la force disponible et la raison de ce maintien.","documents":[{"id":"ch","type":"chaine","disposition":"ligne","titre":"Chaîne de puissance du lit","noeuds":[{"id":"z1","texte":"Moteur"},{"id":"z2","texte":"Engrenage 12 → 48 dents"},{"id":"z3","texte":"Vis-écrou, pas 6 mm"},{"id":"z4","texte":"Plateau"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}],"source":"Situation imaginée pour l’exercice"},{"id":"don","type":"tableau","titre":"Données","colonnes":["Étage","Donnée","Rendement"],"lignes":[["Moteur","3 000 tr/min ; 0,5 N·m","—"],["Engrenage","pignon 12 dents, roue 48 dents","0,92"],["Vis-écrou","pas 6 mm","0,35"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Quelle est la vitesse de montée du plateau, en mm/s ?","aide":"La vis tourne à 3 000 × 12/48 tr/min ; chaque tour fait avancer l’écrou d’un pas.","type":"nombre","unite":"mm/s"},{"enonce":"Quel est le rendement global de la chaîne ? Arrondis au centième.","aide":"Les rendements se multiplient.","type":"nombre"},{"enonce":"Quelle force axiale le plateau reçoit-il, en N ? Arrondis à l’unité.","aide":"P_sortie = η × P_entrée, avec P_entrée = C × ω ; puis F = P_sortie / v.","type":"nombre","unite":"N"},{"enonce":"Le plateau ne redescend pas seul quand le moteur s’arrête. Pourquoi est-ce possible ici ?","aide":"Regarde quel étage a le rendement le plus faible.","type":"choix","options":[{"id":"a","texte":"Le rendement de la vis est excellent, donc elle retient le plateau"},{"id":"b","texte":"Le moteur continue de tourner au ralenti pour maintenir le plateau"},{"id":"c","texte":"Le rendement faible de la vis la rend non réversible : la charge la bloque"},{"id":"d","texte":"L’engrenage est irréversible, ce qui bloque la vis quand il s’arrête"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":75,"tolerance":0},"affichage":"75 mm/s","explication":"Vis : 750 tr/min, soit 750 × 6 = 4 500 mm/min = **75 mm/s**."},{"cle":{"type":"nombre","valeur":0.32,"tolerance":0.005},"affichage":"0,32","explication":"0,92 × 0,35 = **0,322**, soit environ 0,32."},{"cle":{"type":"nombre","valeur":674,"tolerance":6},"affichage":"674 N","explication":"P_entrée = 0,5 × 314 ≈ 157 W ; P_sortie ≈ 0,322 × 157 ≈ 50,6 W ; F = 50,6 / 0,075 ≈ **674 N**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Une vis-écrou à faible rendement (0,35) est **non réversible** : la charge ne peut pas la faire tourner. C’est un défaut pour le rendement, mais une sécurité pour un lit."}]$ex$::jsonb),
  ('5abb438f-6511-5a49-b566-f04bfe4187da'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La plaque du moteur du robot","competence":"modeliser","situation":"Un petit moteur de robot est alimenté sous 12 V. Un ampèremètre donne le courant absorbé ; la fiche du constructeur indique la résistance de l’induit et la constante de couple.","documents":[{"id":"circ","type":"circuit","titre":"Moteur alimenté sous 12 V","branches":[{"de":[0,4],"a":[0,0],"composant":"generateur"},{"de":[0,0],"a":[2,0],"composant":"amperemetre","nom":"A","id":"z1"},{"de":[2,0],"a":[6,0]},{"de":[6,0],"a":[6,4],"composant":"moteur","nom":"M","id":"z2"},{"de":[6,4],"a":[0,4]}]},{"id":"don","type":"tableau","titre":"Fiche du moteur","colonnes":["Donnée","Valeur"],"lignes":[["Tension d’alimentation U","12 V"],["Courant mesuré I","2 A"],["Résistance de l’induit R","1,5 Ω"],["Constante de couple k","0,03 N·m/A"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche le composant qui mesure le courant absorbé par le moteur.","aide":"Il se place en série dans le circuit.","type":"zone","document":"circ","multiple":false},{"enonce":"Quelle est la chute de tension R × I dans l’induit, en V ?","aide":"Multiplie la résistance par le courant.","type":"nombre","unite":"V"},{"enonce":"Quelle est la force contre-électromotrice E, en V ?","aide":"U = E + R × I, donc E = U − R × I.","type":"nombre","unite":"V"},{"enonce":"Quel est le couple électromagnétique du moteur, en N·m ?","aide":"C_em = k × I.","type":"nombre","unite":"N·m"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"L’**ampèremètre A** est en série avec le moteur : il mesure le courant I."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 V","explication":"R × I = 1,5 × 2 = **3 V**."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 V","explication":"E = 12 − 3 = **9 V**."},{"cle":{"type":"nombre","valeur":0.06,"tolerance":0.001},"affichage":"0,06 N·m","explication":"C_em = 0,03 × 2 = **0,06 N·m**."}]$ex$::jsonb),
  ('5abb438f-6511-5a49-b566-f04bfe4187da'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La perceuse sans fil","competence":"calculer","situation":"Le moteur d’une perceuse est alimenté sous 24 V et doit fournir un couple électromagnétique de 0,3 N·m. Avant de prévoir son comportement, on identifie sa constante k par un essai à vide ; on néglige les pertes mécaniques.","documents":[{"id":"essai","type":"tableau","titre":"Essai à vide et fiche du moteur","colonnes":["Donnée","Valeur"],"lignes":[["Vitesse à vide","1 000 tr/min"],["Tension à vide (courant négligeable)","6,28 V"],["Résistance de l’induit R","0,8 Ω"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"À vide, U = E. Calcule la constante k, en N·m/A, arrondie au centième (ω = 2π × 1 000 / 60).","aide":"E = k × Ω, avec Ω en rad/s (environ 104,7 rad/s).","type":"nombre","unite":"N·m/A"},{"enonce":"Quel courant le moteur absorbe-t-il pour fournir 0,3 N·m ?","aide":"C_em = k × I, donc I = C_em / k.","type":"nombre","unite":"A"},{"enonce":"Quelle est la force contre-électromotrice E sous 24 V, en V ?","aide":"E = U − R × I.","type":"nombre","unite":"V"},{"enonce":"À quelle vitesse tourne alors la perceuse, en tr/min ? Arrondis à l’unité.","aide":"Ω = E / k, puis convertis en tr/min avec N = Ω × 60 / 2π.","type":"nombre","unite":"tr/min"},{"enonce":"Quel est le rendement du moteur, en pourcentage ? Arrondis à l’unité.","aide":"Sans pertes mécaniques, η = P_em / P_abs = (E × I) / (U × I).","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.06,"tolerance":0.002},"affichage":"0,06 N·m/A","explication":"Ω ≈ 104,7 rad/s, donc k = 6,28 / 104,7 ≈ **0,06 N·m/A**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0.05},"affichage":"5 A","explication":"I = 0,3 / 0,06 = **5 A**."},{"cle":{"type":"nombre","valeur":20,"tolerance":0.1},"affichage":"20 V","explication":"E = 24 − 0,8 × 5 = **20 V**."},{"cle":{"type":"nombre","valeur":3183,"tolerance":5},"affichage":"3183 tr/min","explication":"Ω = 20 / 0,06 ≈ 333 rad/s, soit **3183 tr/min**."},{"cle":{"type":"nombre","valeur":83,"tolerance":1},"affichage":"83 %","explication":"P_em = 20 × 5 = 100 W ; P_abs = 24 × 5 = 120 W ; η ≈ **83 %**. Les 20 W manquants sont les pertes Joule."}]$ex$::jsonb),
  ('5abb438f-6511-5a49-b566-f04bfe4187da'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Démarrer en douceur","competence":"modeliser","situation":"Un moteur à courant continu est alimenté par un hacheur sous 24 V. Pour ne pas abîmer le bobinage, le hacheur maintient le courant à 6 A pendant tout le démarrage, en augmentant la tension avec le temps. La courbe donne cette tension.","documents":[{"id":"don","type":"tableau","titre":"Fiche du moteur","colonnes":["Donnée","Valeur"],"lignes":[["Résistance de l’induit R","0,8 Ω"],["Constante de couple k","0,06 N·m/A"],["Tension d’alimentation","24 V"],["Courant nominal","3 A"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"cou","type":"graphique","forme":"courbe","titre":"Tension appliquée au moteur pendant le démarrage","categories":["0","0,5","1","1,5","2","2,5","3"],"series":[{"nom":"Tension","valeurs":[4.8,7.5,10.2,12.9,15.6,18.3,21],"teinte":"violet"}],"axeY":{"titre":"Tension appliquée","unite":"V","min":0,"max":25,"pas":5},"axeX":{"titre":"Temps (s)"},"valeurs":false,"source":"Mesures imaginées pour l’exercice"}],"questions":[{"enonce":"Sans limitation, on branche directement le moteur arrêté sous 24 V. Quel courant l’induit reçoit-il, en A ?","aide":"À l’arrêt, E = 0 : I = U / R.","type":"nombre","unite":"A"},{"enonce":"Pour limiter le courant à 6 A à l’arrêt, quelle tension initiale U0 faut-il appliquer, en V ?","aide":"À l’arrêt, U = R × I.","type":"nombre","unite":"V"},{"enonce":"À t = 2 s, la courbe donne la tension appliquée. Quelle est alors la vitesse du moteur, en rad/s ?","aide":"Lis U sur la courbe ; E = U − R × I avec I = 6 A ; puis Ω = E / k.","type":"nombre","unite":"rad/s"},{"enonce":"Quel couple électromagnétique le moteur fournit-il pendant ce démarrage, en N·m ?","aide":"C_em = k × I, avec I = 6 A.","type":"nombre","unite":"N·m"},{"enonce":"La tension monte de façon régulière. À quel instant atteint-elle 24 V ? Arrondis au centième de seconde.","aide":"Calcule la pente de la courbe en V/s, puis résous 4,8 + pente × t = 24.","type":"nombre","unite":"s"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 A","explication":"I = 24 / 0,8 = **30 A**, dix fois le courant nominal."},{"cle":{"type":"nombre","valeur":4.8,"tolerance":0.05},"affichage":"4,8 V","explication":"U0 = 0,8 × 6 = **4,8 V**, valeur que l’on retrouve à t = 0 sur la courbe."},{"cle":{"type":"nombre","valeur":180,"tolerance":1},"affichage":"180 rad/s","explication":"U = 15,6 V ; E = 15,6 − 4,8 = 10,8 V ; Ω = 10,8 / 0,06 = **180 rad/s**."},{"cle":{"type":"nombre","valeur":0.36,"tolerance":0.005},"affichage":"0,36 N·m","explication":"C_em = 0,06 × 6 = **0,36 N·m**, constant tant que le courant l’est."},{"cle":{"type":"nombre","valeur":3.56,"tolerance":0.01},"affichage":"3,56 s","explication":"Pente = (21 − 4,8) / 3 = 5,4 V/s ; t = (24 − 4,8) / 5,4 ≈ **3,56 s**."}]$ex$::jsonb),
