  ('d42efd5a-c8a5-53b8-9558-8af516436254'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un moteur de 6 V sur une batterie de 24 V","competence":"calculer","situation":"Un moteur de 6 V, qui absorbe 1,5 A, doit tourner à sa tension nominale sur une batterie de 24 V. Un hacheur à 20 kHz, dont la sortie MLI se règle de 0 à 255, remplace la résistance série qu’on avait d’abord envisagée.","documents":[{"id":"circ","type":"circuit","titre":"Hacheur série et moteur","branches":[{"de":[0,4],"a":[0,0],"composant":"generateur"},{"de":[0,0],"a":[3,0],"composant":"interrupteur-ferme","nom":"T","id":"z1"},{"de":[3,0],"a":[7,0]},{"de":[7,0],"a":[7,4],"composant":"moteur","nom":"M","id":"z2"},{"de":[7,4],"a":[3,4]},{"de":[3,4],"a":[0,4]},{"de":[3,4],"a":[3,0],"composant":"diode","id":"z3"}]}],"questions":[{"enonce":"Touche la diode de roue libre.","aide":"Elle est montée en parallèle sur le moteur.","type":"zone","document":"circ","multiple":false},{"enonce":"Quel rapport cyclique donne 6 V moyens sous 24 V ?","aide":"α = U_moy / U_alim.","type":"nombre"},{"enonce":"À 20 kHz, le transistor reste fermé pendant une durée t_on. Calcule-la, en µs.","aide":"Période T = 1 / 20 000 s = 50 µs ; t_on = α × T.","type":"nombre","unite":"µs"},{"enonce":"Quelle consigne MLI (de 0 à 255) faut-il envoyer ? Arrondis à l’entier le plus proche.","aide":"Consigne = α × 255.","type":"nombre"},{"enonce":"Avec une résistance série, le moteur (6 V, 1,5 A) serait alimenté sous 24 V. Quel serait le rendement, en pourcentage ?","aide":"La source fournit 24 V × 1,5 A ; le moteur reçoit 6 V × 1,5 A.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La **diode de roue libre** est en parallèle sur le moteur : elle laisse circuler le courant de son inductance quand le transistor s’ouvre."},{"cle":{"type":"nombre","valeur":0.25,"tolerance":0},"affichage":"0,25","explication":"α = 6 / 24 = **0,25**."},{"cle":{"type":"nombre","valeur":12.5,"tolerance":0.05},"affichage":"12,5 µs","explication":"t_on = 0,25 × 50 = **12,5 µs**."},{"cle":{"type":"nombre","valeur":64,"tolerance":0.3},"affichage":"64","explication":"0,25 × 255 = 63,75, soit environ **64**."},{"cle":{"type":"nombre","valeur":25,"tolerance":0.5},"affichage":"25 %","explication":"Puissance source : 36 W ; puissance reçue par le moteur : 9 W ; rendement **25 %**. Un hacheur idéal, lui, ne dissipe presque rien."}]$ex$::jsonb),
  ('d42efd5a-c8a5-53b8-9558-8af516436254'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le pont en H du chariot","competence":"raisonner","situation":"Un chariot de manutention est commandé par un pont en H à quatre interrupteurs K1 à K4. Sur le schéma, le moteur tourne dans un sens. Pendant une manœuvre, le chariot passe par quatre phases.","documents":[{"id":"pont","type":"circuit","titre":"Pont en H, K1 et K4 fermés","branches":[{"de":[0,6],"a":[0,0],"composant":"generateur"},{"de":[0,0],"a":[2,0]},{"de":[2,0],"a":[8,0]},{"de":[0,6],"a":[2,6]},{"de":[2,6],"a":[8,6]},{"de":[2,0],"a":[2,3],"composant":"interrupteur-ferme","nom":"K1","id":"z1"},{"de":[2,3],"a":[2,6],"composant":"interrupteur-ouvert","nom":"K3","id":"z2"},{"de":[8,0],"a":[8,3],"composant":"interrupteur-ouvert","nom":"K2","id":"z3"},{"de":[8,3],"a":[8,6],"composant":"interrupteur-ferme","nom":"K4","id":"z4"},{"de":[2,3],"a":[8,3],"composant":"moteur","nom":"M","id":"z5"}]},{"id":"ph","type":"tableau","titre":"Les quatre phases de la manœuvre","colonnes":["Phase","Vitesse","Couple"],"lignes":[["A","positive","positif"],["B","positive","négatif"],["C","négative","négatif"],["D","négative","positif"]],"enteteLignes":true,"source":"Relevés imaginés pour l’exercice"}],"questions":[{"enonce":"Touche l’interrupteur qui, fermé en même temps que K1, court-circuiterait la source.","aide":"Il faut deux interrupteurs fermés dans la même branche verticale, sans moteur entre eux.","type":"zone","document":"pont","multiple":false},{"enonce":"Comment faire tourner le moteur dans l’autre sens ?","aide":"Il faut que le courant traverse le moteur dans l’autre direction, sans court-circuit.","type":"choix","options":[{"id":"a","texte":"Fermer K3 en gardant K1 et K4 fermés"},{"id":"b","texte":"Ouvrir K1 et K4, puis fermer K2 et K3"},{"id":"c","texte":"Ouvrir seulement K1, sans fermer d’autre interrupteur"},{"id":"d","texte":"Fermer K2 et K4 en gardant K1 fermé"}],"multiple":false},{"enonce":"Associe chaque phase du tableau à son fonctionnement.","aide":"Si vitesse et couple sont de même signe, la machine fournit de la puissance ; sinon elle en reçoit.","type":"association","gauche":[{"id":"g0","texte":"Phase A"},{"id":"g1","texte":"Phase B"},{"id":"g2","texte":"Phase C"},{"id":"g3","texte":"Phase D"}],"droite":[{"id":"d0","texte":"Génératrice, freinage en marche avant"},{"id":"d1","texte":"Moteur, marche arrière"},{"id":"d2","texte":"Génératrice, freinage en marche arrière"},{"id":"d3","texte":"Moteur, marche avant"}]},{"enonce":"En phase B, la vitesse vaut 100 rad/s et le couple −0,4 N·m. Quelle puissance mécanique la machine reçoit-elle de la charge, en W (valeur positive) ?","aide":"P = C × Ω ; le signe négatif signifie que la puissance est reçue.","type":"nombre","unite":"W"},{"enonce":"La machine renvoie 80 % de cette puissance à la batterie pendant 5 s. Quelle énergie est récupérée, en J ?","aide":"Énergie = puissance × durée.","type":"nombre","unite":"J"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**K3** est en série avec K1 dans la même branche : si les deux se ferment ensemble, le générateur est court-circuité."},{"cle":{"type":"choix","ids":["b"]},"explication":"En fermant **K2 et K3** (et en ouvrant K1 et K4), le courant traverse le moteur de droite à gauche : la polarité est inversée."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Vitesse et couple de même signe (A et C) : la machine est **motrice**. De signes opposés (B et D) : elle est **génératrice** et freine."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 W","explication":"P = −0,4 × 100 = −40 W : la charge fournit **40 W** à la machine."},{"cle":{"type":"nombre","valeur":160,"tolerance":0},"affichage":"160 J","explication":"40 × 0,8 = 32 W pendant 5 s : 32 × 5 = **160 J**."}]$ex$::jsonb),
  ('70c8c093-fe6c-5d98-9a87-ef98e15d130a'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La batterie du scooter","competence":"lire-tableau","situation":"Un scooter électrique embarque une batterie lithium-ion dont le constructeur donne la fiche. Son moteur consomme en moyenne 400 W.","documents":[{"id":"fiche","type":"tableau","titre":"Fiche de la batterie","colonnes":["Caractéristique","Valeur"],"lignes":[["Tension nominale","48 V"],["Capacité","20 Ah"],["Masse","6 kg"],["Courant de décharge maximal","40 A"]],"enteteLignes":true,"source":"Fiche imaginée pour l’exercice"}],"questions":[{"enonce":"Touche la valeur qui donne la quantité d’électricité que la batterie peut débiter.","aide":"Cette quantité s’exprime en ampères-heures.","type":"zone","document":"fiche","multiple":false},{"enonce":"Quelle énergie stocke la batterie, en Wh ?","aide":"W = Q × U.","type":"nombre","unite":"Wh"},{"enonce":"Quelle est son énergie massique, en Wh/kg ?","aide":"Divise l’énergie par la masse.","type":"nombre","unite":"Wh/kg"},{"enonce":"On n’utilise que 80 % de l’énergie. Quelle est l’autonomie à 400 W, en heures ? Arrondis au dixième.","aide":"Énergie utilisable = 0,8 × 960 ; autonomie = énergie utilisable / puissance.","type":"nombre","unite":"h"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La **capacité, 20 Ah**, donne la quantité d’électricité que la batterie peut débiter."},{"cle":{"type":"nombre","valeur":960,"tolerance":0},"affichage":"960 Wh","explication":"W = 20 × 48 = **960 Wh**."},{"cle":{"type":"nombre","valeur":160,"tolerance":0},"affichage":"160 Wh/kg","explication":"960 / 6 = **160 Wh/kg**."},{"cle":{"type":"nombre","valeur":1.9,"tolerance":0.05},"affichage":"1,9 h","explication":"0,8 × 960 = 768 Wh ; 768 / 400 = 1,92 h, soit environ **1,9 h**."}]$ex$::jsonb),
  ('70c8c093-fe6c-5d98-9a87-ef98e15d130a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le pack du drone","competence":"calculer","situation":"Une équipe construit la batterie d’un drone avec des cellules lithium-ion identiques. Elle doit choisir l’association de cellules qui respecte le cahier des charges, puis estimer le temps de vol.","documents":[{"id":"cel","type":"tableau","titre":"Une cellule","colonnes":["Caractéristique","Valeur"],"lignes":[["Tension nominale","3,6 V"],["Capacité","3 Ah"]],"enteteLignes":true,"source":"Valeurs typiques arrondies"},{"id":"cdc","type":"tableau","titre":"Cahier des charges du pack","colonnes":["Exigence","Valeur"],"lignes":[["Tension du pack","21,6 V"],["Capacité du pack","9 Ah"],["Consommation moyenne en vol","250 W"],["Décharge maximale autorisée","80 %"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Combien de cellules faut-il associer en série pour obtenir 21,6 V ?","aide":"En série, les tensions s’additionnent.","type":"nombre","unite":"cellules"},{"enonce":"Combien de branches en parallèle faut-il pour obtenir 9 Ah ?","aide":"En parallèle, les capacités s’additionnent.","type":"nombre","unite":"branches"},{"enonce":"Quelle énergie le pack stocke-t-il, en Wh ?","aide":"W = Q × U avec les valeurs du pack.","type":"nombre","unite":"Wh"},{"enonce":"Quel est le temps de vol, en minutes, arrondi à l’unité ? N’utilise que 80 % de l’énergie.","aide":"Temps = énergie utilisable / puissance, en heures ; multiplie par 60.","type":"nombre","unite":"min"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 cellules","explication":"21,6 / 3,6 = **6 cellules** en série."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 branches","explication":"9 / 3 = **3 branches** : le pack est un « 6S3P » de 18 cellules."},{"cle":{"type":"nombre","valeur":194.4,"tolerance":0.1},"affichage":"194,4 Wh","explication":"W = 9 × 21,6 = **194,4 Wh**."},{"cle":{"type":"nombre","valeur":37,"tolerance":1},"affichage":"37 min","explication":"0,8 × 194,4 = 155,5 Wh ; 155,5 / 250 ≈ 0,62 h, soit environ **37 min**."}]$ex$::jsonb),
  ('70c8c093-fe6c-5d98-9a87-ef98e15d130a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Batterie ou supercondensateur ?","competence":"raisonner","situation":"Un robot d’atelier roule sous 36 V avec une batterie de 10 Ah. Il consomme 90 W en moyenne ; on ne décharge jamais la batterie au-delà de 80 %. Par temps froid, la capacité disponible baisse. On compare ensuite avec un supercondensateur.","documents":[{"id":"froid","type":"graphique","forme":"courbe","titre":"Capacité disponible selon la température","categories":["−10","0","10","20"],"series":[{"nom":"Capacité disponible","valeurs":[60,75,90,100],"teinte":"turquoise"}],"axeY":{"titre":"Capacité disponible","unite":"%","min":0,"max":100,"pas":20},"axeX":{"titre":"Température (°C)"},"valeurs":false,"source":"Valeurs imaginées pour l’exercice"},{"id":"sc","type":"tableau","titre":"Le supercondensateur","colonnes":["Caractéristique","Valeur"],"lignes":[["Capacité","100 F"],["Tension maximale","2,7 V"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Quelle part de sa capacité la batterie peut-elle fournir à 0 °C, en pourcentage ?","aide":"Repère 0 sur l’axe horizontal.","type":"nombre","unite":"%"},{"enonce":"À 0 °C, quelle énergie utilisable la batterie offre-t-elle, en Wh ? (énergie totale × part disponible × 80 %)","aide":"Énergie totale = 36 V × 10 Ah.","type":"nombre","unite":"Wh"},{"enonce":"Quelle est alors l’autonomie du robot, en heures ?","aide":"Autonomie = énergie utilisable / puissance.","type":"nombre","unite":"h"},{"enonce":"Quelle énergie le supercondensateur stocke-t-il à pleine tension, en J ? (W = ½ × C × U²)","aide":"Calcule U² = 2,7 × 2,7, puis multiplie par C, puis par ½.","type":"nombre","unite":"J"},{"enonce":"Pourquoi ce supercondensateur ne peut-il pas remplacer la batterie pour l’autonomie ?","aide":"Compare l’énergie stockée, pas la puissance.","type":"choix","options":[{"id":"a","texte":"Sa tension maximale est trop élevée pour alimenter un robot de 36 V"},{"id":"b","texte":"Il se décharge en une seule utilisation et ne peut plus être rechargé"},{"id":"c","texte":"Il ne peut pas fournir de fortes puissances, même pendant un instant"},{"id":"d","texte":"Son énergie, environ 0,1 Wh, est minuscule devant les 360 Wh de la batterie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":75,"tolerance":2},"affichage":"75 %","explication":"À 0 °C, la capacité disponible vaut **75 %**."},{"cle":{"type":"nombre","valeur":216,"tolerance":0.5},"affichage":"216 Wh","explication":"360 × 0,75 × 0,8 = **216 Wh**."},{"cle":{"type":"nombre","valeur":2.4,"tolerance":0.05},"affichage":"2,4 h","explication":"216 / 90 = **2,4 h**."},{"cle":{"type":"nombre","valeur":364.5,"tolerance":1},"affichage":"364,5 J","explication":"W = 0,5 × 100 × 2,7² = **364,5 J**, soit environ 0,1 Wh."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le supercondensateur (≈ 0,1 Wh) stocke environ **3 000 fois moins d’énergie** que la batterie (360 Wh). Son atout est ailleurs : de fortes puissances, sur un très grand nombre de cycles."}]$ex$::jsonb),
  ('ecaaa540-c2f2-58af-b69c-8e0eaf72c682'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le profil du convoyeur","competence":"lire-graphique","situation":"Un convoyeur entraîne des colis sur une bande. Sa vitesse suit un profil en trapèze : il accélère, roule à vitesse constante, puis freine. Le tambour qui entraîne la bande a un rayon de 0,15 m.","documents":[{"id":"prof","type":"graphique","forme":"courbe","titre":"Vitesse de la bande","categories":["0","1","2","3","4","5","6","7","8"],"series":[{"nom":"Vitesse","valeurs":[0,1.5,3,3,3,3,3,1.5,0],"teinte":"violet"}],"axeY":{"titre":"Vitesse","unite":"m/s","min":0,"max":4,"pas":1},"axeX":{"titre":"Temps (s)"},"valeurs":false,"source":"Profil imaginé pour l’exercice"}],"questions":[{"enonce":"Touche l’instant où la bande atteint sa vitesse maximale pour la première fois.","aide":"Cherche où la courbe cesse de monter.","type":"zone","document":"prof","multiple":false},{"enonce":"Quelle est l’accélération pendant la phase de démarrage, en m/s² ?","aide":"Variation de vitesse divisée par la durée de la phase.","type":"nombre","unite":"m/s²"},{"enonce":"Quelle distance la bande parcourt-elle au total, en m ? Calcule l’aire sous la courbe.","aide":"Additionne deux triangles (accélération, freinage) et un rectangle (palier).","type":"nombre","unite":"m"},{"enonce":"Quelle est la vitesse de rotation du tambour au palier, en rad/s ?","aide":"v = ω × R, donc ω = v / R.","type":"nombre","unite":"rad/s"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"La vitesse maximale, 3 m/s, est atteinte à **t = 2 s**."},{"cle":{"type":"nombre","valeur":1.5,"tolerance":0},"affichage":"1,5 m/s²","explication":"a = 3 / 2 = **1,5 m/s²**."},{"cle":{"type":"nombre","valeur":18,"tolerance":0},"affichage":"18 m","explication":"Triangles : ½ × 2 × 3 = 3 m chacun ; rectangle : 4 × 3 = 12 m ; total **18 m**."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 rad/s","explication":"ω = 3 / 0,15 = **20 rad/s**."}]$ex$::jsonb),
  ('ecaaa540-c2f2-58af-b69c-8e0eaf72c682'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La centrifugeuse du laboratoire","competence":"calculer","situation":"Le plateau d’une centrifugeuse accélère régulièrement depuis l’arrêt. Un capteur relève sa vitesse chaque seconde. Un tube est fixé à 0,25 m de l’axe.","documents":[{"id":"rel","type":"tableau","titre":"Vitesse du plateau","colonnes":["Instant (s)","0","1","2","3"],"lignes":[["Vitesse (tr/min)",0,300,600,900]],"enteteLignes":true,"source":"Relevés imaginés pour l’exercice"}],"questions":[{"enonce":"Quelle est la vitesse de rotation à t = 2 s, en rad/s ? Arrondis au dixième.","aide":"ω = 2π × N / 60, avec N = 600 tr/min.","type":"nombre","unite":"rad/s"},{"enonce":"Quelle est l’accélération angulaire, en rad/s² ? Arrondis au dixième.","aide":"La vitesse croît régulièrement : α = ω / t.","type":"nombre","unite":"rad/s²"},{"enonce":"Quel angle le plateau a-t-il décrit en 3 s, en rad ? Arrondis au dixième. θ = ½ × α × t²","aide":"Utilise α = 31,4 rad/s² (valeur exacte : 10π) et t = 3 s.","type":"nombre","unite":"rad"},{"enonce":"Combien cela représente-t-il de tours ?","aide":"Un tour correspond à 2π rad.","type":"nombre","unite":"tours"},{"enonce":"Quelle est la vitesse du tube à t = 3 s, en m/s ? Arrondis au dixième.","aide":"ω vaut 900 tr/min, soit environ 94,2 rad/s ; v = ω × R.","type":"nombre","unite":"m/s"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":62.8,"tolerance":0.05},"affichage":"62,8 rad/s","explication":"ω = 2π × 600 / 60 ≈ **62,8 rad/s**."},{"cle":{"type":"nombre","valeur":31.4,"tolerance":0.05},"affichage":"31,4 rad/s²","explication":"α = 62,8 / 2 ≈ **31,4 rad/s²**."},{"cle":{"type":"nombre","valeur":141.4,"tolerance":0.1},"affichage":"141,4 rad","explication":"θ = ½ × 31,4 × 9 ≈ **141,4 rad**."},{"cle":{"type":"nombre","valeur":22.5,"tolerance":0.05},"affichage":"22,5 tours","explication":"141,4 / 2π = **22,5 tours**."},{"cle":{"type":"nombre","valeur":23.6,"tolerance":0.05},"affichage":"23,6 m/s","explication":"v = 94,2 × 0,25 ≈ **23,6 m/s**."}]$ex$::jsonb),
  ('ecaaa540-c2f2-58af-b69c-8e0eaf72c682'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le chariot du portique","competence":"modeliser","situation":"Le chariot d’un portique de chargement parcourt 4 m avec un profil de vitesse en trapèze. On veut prévoir la durée du trajet, puis voir l’effet d’une accélération plus douce.","documents":[{"id":"cdc","type":"tableau","titre":"Cahier des charges","colonnes":["Exigence","Valeur"],"lignes":[["Course totale","4 m"],["Vitesse maximale","1,5 m/s"],["Accélération (et décélération)","3 m/s²"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"},{"id":"trap","type":"schema","titre":"Profil de vitesse en trapèze","largeur":340,"hauteur":200,"elements":[{"forme":"ligne","de":[30,160],"a":[320,160],"fleche":"fin"},{"forme":"ligne","de":[50,170],"a":[50,30],"fleche":"fin"},{"forme":"ligne","de":[50,160],"a":[100,60],"id":"z1","zone":true},{"forme":"ligne","de":[100,60],"a":[230,60],"id":"z2","zone":true},{"forme":"ligne","de":[230,60],"a":[280,160],"id":"z3","zone":true},{"forme":"texte","x":58,"y":26,"texte":"v (m/s)","taille":"petit"},{"forme":"texte","x":316,"y":178,"texte":"t (s)","ancre":"fin","taille":"petit"},{"forme":"texte","x":165,"y":50,"texte":"v max","ancre":"milieu","taille":"petit"}]}],"questions":[{"enonce":"Touche la phase pendant laquelle le chariot parcourt le plus de chemin.","aide":"Compare la distance de chaque phase : les rampes sont courtes, la phase à vitesse constante peut être longue.","type":"zone","document":"trap","multiple":false},{"enonce":"Combien de temps dure la phase d’accélération, en s ?","aide":"a = Δv / Δt, donc Δt = v max / a.","type":"nombre","unite":"s"},{"enonce":"Quelle distance le chariot parcourt-il pendant l’accélération, en m ?","aide":"Aire d’un triangle : ½ × durée × vitesse atteinte.","type":"nombre","unite":"m"},{"enonce":"Quelle est la durée totale du trajet de 4 m, en s ? Arrondis au centième.","aide":"Distance au palier = 4 − 2 × 0,375 ; durée du palier = distance / vitesse.","type":"nombre","unite":"s"},{"enonce":"Avec une accélération réduite à 1,5 m/s², quelle est la nouvelle durée totale, en s ? Arrondis au centième.","aide":"Reprends les mêmes étapes : durée de rampe, distance de rampe, palier.","type":"nombre","unite":"s"}]}$ex$::jsonb,
