  ('c39e4d0f-2c54-5ab1-93c2-e05f2a30ce66'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le chariot de l’atelier","competence":"observer-schema","situation":"Un chariot de 40 kg est poussé sur un sol plat par un moteur qui exerce une force de 120 N. Les frottements exercent une force constante de 40 N. Il part de l’arrêt.","documents":[{"id":"sch","type":"schema","titre":"Forces horizontales sur le chariot","largeur":340,"hauteur":160,"source":"Situation imaginée pour l’exercice","elements":[{"forme":"ligne","de":[20,125],"a":[320,125]},{"forme":"rect","x":110,"y":70,"l":120,"h":55,"texte":"m = 40 kg"},{"forme":"ligne","de":[20,95],"a":[108,95],"fleche":"fin","id":"z1","zone":true},{"forme":"texte","x":64,"y":84,"texte":"120 N","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[320,95],"a":[232,95],"fleche":"fin","id":"z2","zone":true},{"forme":"texte","x":276,"y":84,"texte":"40 N","ancre":"milieu","taille":"petit"}]}],"questions":[{"enonce":"Touche la force qui s’oppose au mouvement du chariot.","aide":"Le chariot avance vers la droite.","type":"zone","document":"sch","multiple":false},{"enonce":"Quelle est la somme des forces horizontales, en N ?","aide":"Soustrais la force qui freine de la force motrice.","type":"nombre","unite":"N"},{"enonce":"Quelle est l’accélération du chariot, en m/s² ?","aide":"Somme des forces = m × a.","type":"nombre","unite":"m/s²"},{"enonce":"Quelle est sa vitesse après 3 s, en m/s ?","aide":"Le chariot part de l’arrêt avec une accélération constante : v = a × t.","type":"nombre","unite":"m/s"}]}$ex$::jsonb,
