  ('c39e4d0f-2c54-5ab1-93c2-e05f2a30ce66'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La cabine du chantier","competence":"calculer","situation":"Une cabine de chantier chargée, de 600 kg au total, monte entre deux étages. Le câble tire vers le haut avec une force T ; le poids est m × g, avec g = 9,81 m/s². On isole la cabine et on étudie trois phases.","documents":[{"id":"ph","type":"tableau","titre":"Les trois phases de la montée","colonnes":["Phase","Accélération (m/s²)","Durée (s)"],"lignes":[["Démarrage","+ 0,8",2],["Montée à vitesse constante","0",10],["Arrêt","− 0,8",2]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Quelle est la tension du câble au démarrage, en N ?","aide":"T − m × g = m × a, donc T = m × (g + a).","type":"nombre","unite":"N"},{"enonce":"Quelle est la tension du câble à vitesse constante, en N ?","aide":"L’accélération est nulle : le câble équilibre exactement le poids.","type":"nombre","unite":"N"},{"enonce":"Quelle est la tension du câble pendant l’arrêt, en N ?","aide":"Ici l’accélération est dirigée vers le bas : T = m × (g − 0,8).","type":"nombre","unite":"N"},{"enonce":"Sur quelle phase dimensionne-t-on le câble ?","aide":"Compare les trois tensions calculées.","type":"choix","options":[{"id":"a","texte":"Le démarrage, car l’effort dans le câble y est le plus grand"},{"id":"b","texte":"Aucune en particulier : l’effort est le même dans les trois phases"},{"id":"c","texte":"L’arrêt, car la cabine y perd de la vitesse et risque de chuter"},{"id":"d","texte":"La montée à vitesse constante, car elle dure le plus longtemps"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":6366,"tolerance":1},"affichage":"6366 N","explication":"T = 600 × (9,81 + 0,8) = **6 366.000 000 000 001 N**."},{"cle":{"type":"nombre","valeur":5886,"tolerance":1},"affichage":"5886 N","explication":"T = 600 × 9,81 = **5 886 N**."},{"cle":{"type":"nombre","valeur":5406,"tolerance":1},"affichage":"5406 N","explication":"T = 600 × (9,81 − 0,8) = **5 406 N**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La tension est maximale au **démarrage** : c’est le pire moment, celui sur lequel on dimensionne, pas la moyenne."}]$ex$::jsonb),
  ('c39e4d0f-2c54-5ab1-93c2-e05f2a30ce66'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Choisir le moteur du tambour","competence":"modeliser","situation":"Un moteur doit entraîner un tambour selon le profil de vitesse ci-dessous. Le tambour a un moment d’inertie J = 0,8 kg·m² et subit un couple de frottement constant de 4 N·m. On cherche quel couple le moteur doit fournir à chaque phase.","documents":[{"id":"don","type":"tableau","titre":"Données du tambour","colonnes":["Donnée","Valeur"],"lignes":[["Moment d’inertie J","0,8 kg·m²"],["Couple de frottement","4 N·m"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"om","type":"graphique","forme":"courbe","titre":"Vitesse du tambour","categories":["0","1","2","3","4","5","6","7","8"],"series":[{"nom":"Vitesse","valeurs":[0,50,100,150,150,150,100,50,0],"teinte":"violet"}],"axeY":{"titre":"Vitesse","unite":"rad/s","min":0,"max":200,"pas":50},"axeX":{"titre":"Temps (s)"},"valeurs":false,"source":"Profil imaginé pour l’exercice"}],"questions":[{"enonce":"Quelle est l’accélération angulaire pendant le démarrage, en rad/s² ?","aide":"Lis la variation de vitesse sur la courbe, puis divise par la durée.","type":"nombre","unite":"rad/s²"},{"enonce":"Quel couple le moteur doit-il fournir pendant le démarrage, en N·m ?","aide":"C_moteur − C_frottement = J × α.","type":"nombre","unite":"N·m"},{"enonce":"Quel couple le moteur fournit-il pendant le freinage (de 5 s à 8 s), en N·m ? Le résultat est négatif.","aide":"Ici α est négatif : α = −150 / 3 = −50 rad/s².","type":"nombre","unite":"N·m"},{"enonce":"Quelle puissance le moteur développe-t-il à la fin du démarrage (t = 3 s), en W ?","aide":"P = C × ω, avec le couple du démarrage et ω = 150 rad/s.","type":"nombre","unite":"W"},{"enonce":"Quelle phase fixe le couple maximal que doit fournir le moteur ?","aide":"Compare 44 N·m, 4 N·m et 36 N·m en valeur absolue.","type":"choix","options":[{"id":"a","texte":"Le freinage, parce que son couple est négatif"},{"id":"b","texte":"Le palier, parce que c’est la phase qui dure le plus longtemps"},{"id":"c","texte":"Aucune : le couple est partout égal à 4 N·m"},{"id":"d","texte":"L’accélération, car elle demande le plus grand couple en valeur absolue"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 rad/s²","explication":"α = 150 / 3 = **50 rad/s²**."},{"cle":{"type":"nombre","valeur":44,"tolerance":0.1},"affichage":"44 N·m","explication":"C_moteur = 4 + 0,8 × 50 = **44 N·m**."},{"cle":{"type":"nombre","valeur":-36,"tolerance":0.1},"affichage":"−36 N·m","explication":"C_moteur = 4 + 0,8 × (−50) = **−36 N·m** : le moteur doit freiner."},{"cle":{"type":"nombre","valeur":6600,"tolerance":10},"affichage":"6600 W","explication":"P = 44 × 150 = **6 600 W**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le démarrage demande **44 N·m**, contre 4 N·m au palier et 36 N·m en valeur absolue au freinage : c’est lui qui dimensionne le moteur."}]$ex$::jsonb),
  ('5e0e0ac8-0d5c-5183-b0bb-94642077c732'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les pièces du tapis roulant","competence":"calculer","situation":"Un atelier étudie trois pièces qui tournent autour du même axe de rotation dans un petit tapis roulant. Leurs caractéristiques sont relevées dans le tableau.","documents":[{"id":"pieces","type":"tableau","titre":"Les trois pièces","colonnes":["Pièce","Forme","Masse (kg)","Rayon ou distance (m)"],"lignes":[["A","Disque plein",6,"0,2"],["B","Anneau mince",4,"0,2"],["C","Masse ponctuelle","0,5","0,4"]],"enteteLignes":true,"source":"Données imaginées pour l’exercice"}],"questions":[{"enonce":"Quel est le moment d’inertie de la pièce A (disque plein), en kg·m² ?","aide":"Pour un disque plein : J = ½ × m × R².","type":"nombre","unite":"kg·m²"},{"enonce":"Quel est le moment d’inertie de la masse ponctuelle C, en kg·m² ?","aide":"Pour une masse ponctuelle : J = m × r².","type":"nombre","unite":"kg·m²"},{"enonce":"Touche la pièce dont le moment d’inertie est le plus grand.","aide":"Calcule aussi celui de l’anneau : J = m × R².","type":"zone","document":"pieces","multiple":false},{"enonce":"Les trois pièces tournent autour du même axe. Quelle inertie totale, en kg·m² ?","aide":"Quand l’axe est le même, les inerties s’additionnent.","type":"nombre","unite":"kg·m²"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.12,"tolerance":0},"affichage":"0,12 kg·m²","explication":"J = ½ × 6 × 0,2² = ½ × 6 × 0,04 = **0,12 kg·m²**."},{"cle":{"type":"nombre","valeur":0.08,"tolerance":0},"affichage":"0,08 kg·m²","explication":"J = 0,5 × 0,4² = 0,5 × 0,16 = **0,08 kg·m²**."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"L’anneau : J = 4 × 0,2² = 0,16 kg·m², contre 0,12 pour le disque et 0,08 pour la masse ponctuelle. C’est la **pièce B**."},{"cle":{"type":"nombre","valeur":0.36,"tolerance":0},"affichage":"0,36 kg·m²","explication":"0,12 + 0,16 + 0,08 = **0,36 kg·m²**."}]$ex$::jsonb),
  ('5e0e0ac8-0d5c-5183-b0bb-94642077c732'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le plateau du manège","competence":"modeliser","situation":"Le plateau d’un petit manège est entraîné par un moteur à travers un réducteur. Le moteur « ressent » l’inertie du plateau, mais réduite : on veut la calculer pour choisir le couple du moteur.","documents":[{"id":"don","type":"tableau","titre":"Données","colonnes":["Élément","Caractéristique"],"lignes":[["Rotor du moteur","J_m = 0,002 kg·m²"],["Réducteur","k = ω_plateau / ω_moteur = 1/8"],["Plateau","Disque plein, 40 kg, rayon 0,5 m"]],"enteteLignes":true,"source":"Données imaginées pour l’exercice"},{"id":"cha","type":"chaine","disposition":"ligne","noeuds":[{"id":"z1","texte":"Moteur"},{"id":"z2","texte":"Réducteur"},{"id":"z3","texte":"Plateau"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"}]}],"questions":[{"enonce":"Quelle est l’inertie du plateau autour de son propre axe, en kg·m² ?","aide":"Disque plein : J = ½ × m × R².","type":"nombre","unite":"kg·m²"},{"enonce":"Quelle inertie du plateau le moteur ressent-il, en kg·m² (arrondi au millième) ?","aide":"Multiplie J_c par k², avec k = 1/8.","type":"nombre","unite":"kg·m²"},{"enonce":"Quelle est l’inertie équivalente ramenée sur l’arbre moteur, en kg·m² (arrondi au millième) ?","aide":"N’oublie pas le rotor : J_eq = J_m + J_c × k².","type":"nombre","unite":"kg·m²"},{"enonce":"Pour accélérer le moteur à 300 rad/s², quel couple faut-il, en N·m (à 0,1 près, frottements exclus) ?","aide":"C = J_eq × accélération angulaire.","type":"nombre","unite":"N·m"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 kg·m²","explication":"J_c = ½ × 40 × 0,5² = ½ × 40 × 0,25 = **5 kg·m²**."},{"cle":{"type":"nombre","valeur":0.078,"tolerance":0.0005},"affichage":"0,078 kg·m²","explication":"k² = 1/64, donc J_c × k² = 5 / 64 ≈ **0,078 kg·m²**."},{"cle":{"type":"nombre","valeur":0.08,"tolerance":0.0005},"affichage":"0,08 kg·m²","explication":"J_eq = 0,002 + 0,078 ≈ **0,080 kg·m²**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0.1},"affichage":"24 N·m","explication":"C = 0,080 × 300 ≈ **24 N·m**."}]$ex$::jsonb),
  ('5e0e0ac8-0d5c-5183-b0bb-94642077c732'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le treuil de chantier","competence":"modeliser","situation":"Un petit treuil lève une charge avec un tambour, entraîné par un moteur à travers un réducteur. On veut l’inertie ramenée sur l’arbre moteur pour vérifier le démarrage.","documents":[{"id":"treuil","type":"tableau","titre":"Données du treuil","colonnes":["Élément","Caractéristique"],"lignes":[["Rotor du moteur","J_m = 0,0004 kg·m²"],["Réducteur","k = ω_tambour / ω_moteur = 1/20"],["Tambour (sur son axe)","J_t = 0,02 kg·m², rayon R = 0,1 m"],["Charge levée","m = 50 kg"]],"enteteLignes":true,"source":"Données imaginées pour l’exercice"},{"id":"cha","type":"chaine","disposition":"ligne","noeuds":[{"id":"z1","texte":"Moteur"},{"id":"z2","texte":"Réducteur"},{"id":"z3","texte":"Tambour"},{"id":"z4","texte":"Charge"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4","texte":"câble"}]}],"questions":[{"enonce":"La charge est levée par le câble du tambour. Quelle inertie compte-t-elle côté tambour, en kg·m² ?","aide":"Une masse levée par un tambour compte pour m × R².","type":"nombre","unite":"kg·m²"},{"enonce":"Quelle est l’inertie totale côté tambour (tambour + charge), en kg·m² ?","aide":"Additionne l’inertie du tambour et celle de la charge.","type":"nombre","unite":"kg·m²"},{"enonce":"Quelle est l’inertie équivalente sur l’arbre moteur, en kg·m² ?","aide":"J_eq = J_m + (inertie côté tambour) × k², avec k² = 1/400.","type":"nombre","unite":"kg·m²"},{"enonce":"La charge doit monter à 0,4 m/s. À quelle vitesse tourne le moteur, en rad/s ?","aide":"D’abord ω_tambour = v / R, puis divise par k.","type":"nombre","unite":"rad/s"},{"enonce":"Quelle part de l’inertie équivalente vient du rotor du moteur, en % (arrondi à l’unité) ?","aide":"Divise J_m par J_eq.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.5,"tolerance":0},"affichage":"0,5 kg·m²","explication":"m × R² = 50 × 0,1² = 50 × 0,01 = **0,5 kg·m²**."},{"cle":{"type":"nombre","valeur":0.52,"tolerance":0},"affichage":"0,52 kg·m²","explication":"0,02 + 0,5 = **0,52 kg·m²**."},{"cle":{"type":"nombre","valeur":0.0017,"tolerance":0.00001},"affichage":"0,0017 kg·m²","explication":"Côté tambour ramené : 0,52 / 400 = 0,0013. J_eq = 0,0004 + 0,0013 = **0,0017 kg·m²**."},{"cle":{"type":"nombre","valeur":80,"tolerance":0},"affichage":"80 rad/s","explication":"ω_tambour = 0,4 / 0,1 = 4 rad/s ; ω_moteur = 4 × 20 = **80 rad/s**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0.5},"affichage":"24 %","explication":"0,0004 / 0,0017 ≈ 0,235, soit environ **24 %** : le rotor est loin d’être négligeable."}]$ex$::jsonb),
