   $ex${"titre":"Le robot qui dérive","competence":"argumenter","situation":"Au projet, l’équipe de Nour a vu son robot à deux roues dériver. Elle veut en tirer une question de Grand oral, avec le projet comme exemple et des chiffres parlants.","documents":[{"id":"jdb","type":"texte","genre":"recit","titre":"Journal de projet","auteur":"Texte écrit pour l’exercice","blocs":["Jeudi : on envoie la même consigne aux deux moteurs, 10 rad/s, mais le robot tourne peu à peu vers la droite.","Vendredi : les codeurs mesurent les vitesses réelles des deux roues. Le rayon des roues est de 0,05 m et l’entraxe (la distance entre les deux roues) de 0,20 m."]},{"id":"mes","type":"tableau","titre":"Relevés des codeurs","colonnes":["Grandeur","Roue gauche","Roue droite"],"lignes":[["Consigne (rad/s)",10,10],["Mesure (rad/s)","9,8","9,2"]],"enteteLignes":true,"source":"Mesures imaginées pour l’exercice"}],"questions":[{"enonce":"Quelle est la vitesse de la roue gauche, en m/s ? (v = ω × R)","aide":"Multiplie 9,8 rad/s par le rayon de la roue.","type":"nombre","unite":"m/s"},{"enonce":"De combien la roue gauche va-t-elle plus vite que la roue droite, en m/s ?","aide":"Calcule la vitesse de la roue droite de la même façon.","type":"nombre","unite":"m/s"},{"enonce":"La vitesse de rotation du robot vaut (écart de vitesse) / (entraxe). Combien, en rad/s ?","aide":"Divise l’écart de vitesse par 0,20 m.","type":"nombre","unite":"rad/s"},{"enonce":"Quelle question générale l’équipe peut-elle présenter au Grand oral ?","aide":"La bonne question dépasse le prototype.","type":"choix","options":[{"id":"a","texte":"Pourquoi un robot à deux roues ne va-t-il pas droit tout seul ?"},{"id":"b","texte":"Qu’est-ce qu’un codeur incrémental et à quoi sert-il ?"},{"id":"c","texte":"Comment fonctionne le moteur de mon robot à deux roues ?"},{"id":"d","texte":"Quelles sont les étapes de mon projet de robot de l’an passé ?"}],"multiple":false},{"enonce":"Quel début de réponse utilise le projet comme exemple, sans le réciter ?","aide":"Cherche la phrase qui avance un argument avec un chiffre.","type":"choix","options":[{"id":"a","texte":"Un robot dérive car ses roues ne vont jamais à la même vitesse : sur notre prototype, 9,8 contre 9,2 rad/s suffisent à le dévier"},{"id":"b","texte":"Un robot à deux roues comporte deux moteurs, deux roues, un châssis, une batterie, un microcontrôleur et deux codeurs"},{"id":"c","texte":"Notre projet a duré 48 heures : nous avons rédigé le cahier des charges, choisi les moteurs, puis monté le châssis"},{"id":"d","texte":"Pour répondre, je vais réciter les dix pages de notre rapport de projet, en commençant par le sommaire de l’équipe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.49,"tolerance":0.001},"affichage":"0,49 m/s","explication":"v = 9,8 × 0,05 = **0,49 m/s**."},{"cle":{"type":"nombre","valeur":0.03,"tolerance":0.0005},"affichage":"0,03 m/s","explication":"Roue droite : 9,2 × 0,05 = 0,46 m/s. Écart : 0,49 − 0,46 = **0,03 m/s**."},{"cle":{"type":"nombre","valeur":0.15,"tolerance":0.001},"affichage":"0,15 rad/s","explication":"0,03 / 0,20 = **0,15 rad/s** : assez pour que le robot quitte sa ligne droite en quelques secondes."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est un **problème général** : la réponse utilise le projet comme exemple au lieu de le raconter."},{"cle":{"type":"choix","ids":["a"]},"explication":"La bonne réponse **avance un argument** et l’appuie sur des chiffres du projet, sans le raconter ni l’énumérer."}]$ex$::jsonb),
