   $ex${"titre":"Le câble de l’enseigne","competence":"calculer","situation":"Une enseigne de boutique est suspendue à un tirant en acier. On vérifie que la barre résiste à l’effort qui la tire.","documents":[{"id":"don","type":"tableau","titre":"Données du tirant","colonnes":["Donnée","Valeur"],"lignes":[["Matériau","Acier"],["Limite élastique Re","235 MPa"],["Section S","50 mm²"],["Effort de traction N","4 000 N"]],"enteteLignes":true,"source":"Données imaginées pour l’exercice"}],"questions":[{"enonce":"Quelle contrainte normale subit le tirant, en MPa ?","aide":"σ = N / S, avec N en newtons et S en mm².","type":"nombre","unite":"MPa"},{"enonce":"Touche la valeur de la limite élastique du tirant.","aide":"Cherche la ligne « Limite élastique Re ».","type":"zone","document":"don","multiple":false},{"enonce":"Quel coefficient de sécurité obtient-on (Re / σ), arrondi au dixième ?","aide":"Divise la limite élastique par la contrainte calculée.","type":"nombre"},{"enonce":"On impose σ ≤ Re / s avec s = 2. Le tirant respecte-t-il cette condition ?","aide":"Calcule d’abord Re / 2.","type":"choix","options":[{"id":"a","texte":"Oui, car 80 MPa est inférieur à Re / s = 117,5 MPa"},{"id":"b","texte":"Oui, car 80 MPa est supérieur à Re / s = 117,5 MPa"},{"id":"c","texte":"Non, car 80 MPa est inférieur à Re / s = 117,5 MPa"},{"id":"d","texte":"Non, car 80 MPa est supérieur à Re / s = 117,5 MPa"}],"multiple":false}]}$ex$::jsonb,
