  ('b27407cc-a16b-50b4-a6c0-9696d1e4e01a'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"L’essai sur l’alliage léger","competence":"lire-graphique","situation":"Un laboratoire tire une éprouvette d’aluminium jusqu’à la rupture et trace la contrainte σ en fonction de l’allongement relatif ε, exprimé en millièmes (‰).","documents":[{"id":"essai","type":"graphique","forme":"courbe","titre":"Courbe de traction","categories":["0","1","2","3","4","5","6"],"series":[{"nom":"Contrainte","valeurs":[0,70,140,210,240,255,260],"teinte":"violet"}],"axeY":{"titre":"Contrainte σ","unite":"MPa","min":0,"max":300,"pas":50},"axeX":{"titre":"Allongement relatif ε (‰)"},"valeurs":false,"source":"Essai imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le dernier point qui reste aligné sur la droite de départ.","aide":"Après ce point, la courbe s’infléchit : la déformation devient permanente.","type":"zone","document":"essai","multiple":false},{"enonce":"Quel est le module d’Young de l’alliage, en MPa ? (σ = E × ε, avec ε = 0,002 au point 2 ‰)","aide":"E = σ / ε, dans le domaine élastique.","type":"nombre","unite":"MPa"},{"enonce":"Quelle est la résistance à la rupture Rm lue sur la courbe, en MPa ?","aide":"C’est la contrainte maximale atteinte.","type":"nombre","unite":"MPa"},{"enonce":"Un tirant de 400 mm de long est tendu à 140 MPa. De combien s’allonge-t-il, en mm ?","aide":"ε = σ / E, puis ΔL = ε × L0.","type":"nombre","unite":"mm"},{"enonce":"Avec un coefficient de sécurité s = 1,5, quelle contrainte admissible retient-on, en MPa ?","aide":"σ admissible = Re / s, avec Re lue plus haut.","type":"nombre","unite":"MPa"}]}$ex$::jsonb,
