  ('b27407cc-a16b-50b4-a6c0-9696d1e4e01a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les tirants de la passerelle","competence":"modeliser","situation":"Une passerelle piétonne est suspendue à des tirants d’acier ronds. Chaque tirant reprend 12 kN. Comme des personnes sont en jeu, on retient un coefficient de sécurité s = 2,5. Acier : Re = 355 MPa, E = 210 000 MPa.","documents":[{"id":"sch","type":"schema","titre":"Un tirant de la passerelle","largeur":340,"hauteur":210,"source":"Schéma imaginé pour l’exercice","elements":[{"forme":"rect","x":90,"y":20,"l":140,"h":12,"motif":"hachures"},{"forme":"rect","x":155,"y":32,"l":10,"h":100,"id":"z1","zone":true},{"forme":"rect","x":120,"y":132,"l":80,"h":34,"arrondi":4,"texte":"12 kN"},{"forme":"ligne","de":[215,34],"a":[215,130],"fleche":"deux"},{"forme":"texte","x":225,"y":86,"texte":"L0 = 3 m","taille":"petit","ancre":"debut"},{"forme":"texte","x":160,"y":186,"texte":"Tirant rond d’acier","taille":"petit","ancre":"milieu"}]},{"id":"cat","type":"tableau","titre":"Catalogue des tirants ronds","colonnes":["Diamètre","Section (mm²)"],"lignes":[["Ø 8 mm","50,3"],["Ø 10 mm","78,5"],["Ø 12 mm","113,1"],["Ø 14 mm","153,9"]],"enteteLignes":true,"source":"Catalogue imaginé pour l’exercice"}],"questions":[{"enonce":"Quelle contrainte admissible retient-on, en MPa ?","aide":"σ admissible = Re / s.","type":"nombre","unite":"MPa"},{"enonce":"Quelle section minimale faut-il, en mm² (à 0,5 près) ? Attention, 12 kN = 12 000 N.","aide":"S = N / σ admissible.","type":"nombre","unite":"mm²"},{"enonce":"Touche le plus petit diamètre du catalogue dont la section dépasse 84,5 mm².","aide":"Compare 84,5 mm² à la colonne des sections.","type":"zone","document":"cat","multiple":false},{"enonce":"Quelle contrainte subirait un tirant de Ø 10 mm, en MPa (à 1 MPa près) ?","aide":"σ = 12 000 / 78,5.","type":"nombre","unite":"MPa"},{"enonce":"Avec le Ø 12 mm, de combien un tirant de 3 m s’allonge-t-il, en mm (à 0,1 près) ?","aide":"σ = 12 000 / 113,1, puis ε = σ / E et ΔL = ε × L0 (en mm).","type":"nombre","unite":"mm"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":142,"tolerance":0.5},"affichage":"142 MPa","explication":"355 / 2,5 = **142 MPa**."},{"cle":{"type":"nombre","valeur":84.5,"tolerance":0.5},"affichage":"84,5 mm²","explication":"S = 12 000 / 142 ≈ **84,5 mm²**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Ø 10 mm n’offre que 78,5 mm², trop peu ; **Ø 12 mm** offre 113,1 mm² : c’est le plus petit qui convient."},{"cle":{"type":"nombre","valeur":153,"tolerance":1},"affichage":"153 MPa","explication":"σ = 12 000 / 78,5 ≈ **153 MPa**, au-dessus des 142 MPa admissibles : Ø 10 mm est refusé."},{"cle":{"type":"nombre","valeur":1.5,"tolerance":0.05},"affichage":"1,5 mm","explication":"σ ≈ 106,1 MPa ; ε = 106,1 / 210 000 ≈ 0,0005 ; ΔL = 0,0005 × 3 000 ≈ **1,5 mm**."}]$ex$::jsonb),
  ('74fd445d-b1c3-5842-82ff-ddbbb0e39568'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La règle sur deux livres","competence":"observer-schema","situation":"Une poutre repose sur deux appuis et porte une charge F en son milieu. Elle se courbe vers le bas : on observe ce qui se passe dans l’épaisseur.","documents":[{"id":"pou","type":"schema","titre":"Poutre sur deux appuis","largeur":360,"hauteur":230,"source":"Schéma imaginé pour l’exercice","elements":[{"forme":"rect","x":50,"y":90,"l":260,"h":20,"teinte":"gris","motif":"clair","id":"z1","zone":true},{"forme":"rect","x":50,"y":110,"l":260,"h":20,"teinte":"gris","motif":"clair","id":"z2","zone":true},{"forme":"rect","x":50,"y":130,"l":260,"h":20,"teinte":"gris","motif":"clair","id":"z3","zone":true},{"forme":"polygone","points":[[60,150],[45,175],[75,175]],"motif":"plein"},{"forme":"polygone","points":[[300,150],[285,175],[315,175]],"motif":"plein"},{"forme":"ligne","de":[180,40],"a":[180,88],"fleche":"fin"},{"forme":"texte","x":192,"y":52,"texte":"F","taille":"petit","ancre":"debut"}]},{"id":"sec","type":"tableau","titre":"Section de la poutre","colonnes":["Grandeur","Valeur"],"lignes":[["Base b","30 mm"],["Hauteur h (sens de la flexion)","60 mm"]],"enteteLignes":true,"source":"Données imaginées pour l’exercice"}],"questions":[{"enonce":"Touche la bande de la poutre qui est la plus tendue.","aide":"La poutre se courbe vers le bas : regarde quel côté s’allonge.","type":"zone","document":"pou","multiple":false},{"enonce":"Touche la bande où la contrainte est nulle.","aide":"Elle se trouve entre la zone comprimée et la zone tendue.","type":"zone","document":"pou","multiple":false},{"enonce":"Quel est le moment quadratique de la section 30 × 60 mm fléchie dans le sens des 60 mm, en mm⁴ ?","aide":"I = b × h³ / 12.","type":"nombre","unite":"mm⁴"},{"enonce":"Posée à plat, la poutre ne plie plus que dans le sens des 30 mm. Quel est alors I, en mm⁴ ?","aide":"Échange les rôles : b = 60 mm et h = 30 mm.","type":"nombre","unite":"mm⁴"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La poutre se creuse vers le bas : les fibres du bas s’allongent, donc elles sont **tendues**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"La **fibre neutre**, au milieu, n’est ni tendue ni comprimée."},{"cle":{"type":"nombre","valeur":540000,"tolerance":0},"affichage":"540 000 mm⁴","explication":"I = 30 × 60³ / 12 = 30 × 216 000 / 12 = **540 000 mm⁴**."},{"cle":{"type":"nombre","valeur":135000,"tolerance":0},"affichage":"135 000 mm⁴","explication":"I = 60 × 30³ / 12 = 60 × 27 000 / 12 = **135 000 mm⁴**, soit quatre fois moins."}]$ex$::jsonb),
  ('74fd445d-b1c3-5842-82ff-ddbbb0e39568'::uuid, 2, 2, 10, 35, 5,
